insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('good-enough-standard-setter', 'Good Enough Standard Setter', 'worksheet'::resource_kind, 'A worksheet for setting a good-enough bar for a task before the client starts it.', 'Use it to loosen an all-or-nothing standard before a task begins.', array['Adults', 'Teens']::text[], '15 minutes', 'Before a task that tends to spiral into overwork, the client writes what good enough would look like, separately from what perfect would look like, then commits in writing to stopping at the good-enough line. Useful right before a paper, a work email, or a cleanup that usually runs long. Revisit afterward: did stopping at good enough cost anything the client actually cares about, or only the discomfort of stopping?', '[{"id": "f0", "type": "textarea", "label": "The task I''m about to start"}, {"id": "f1", "type": "textarea", "label": "What \"perfect\" would look like here"}, {"id": "f2", "type": "textarea", "label": "What \"good enough\" looks like here"}, {"id": "f3", "type": "textarea", "label": "My stopping point, in writing"}, {"id": "f4", "type": "textarea", "label": "What happened when I stopped there"}]'::jsonb, array['perfectionism', 'standards', 'task initiation']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('session-opening-check-in-card', 'Session Opening Check-In Card', 'worksheet'::resource_kind, 'A short scale-and-prompt card clients fill out before session to start with real data.', 'Use it to open session with where the client actually is, not a guess.', array['Adults', 'Teens', 'Groups']::text[], 'Five minutes', 'Handed over before session starts, this card asks for a quick number and a word rather than a full recap. It gives the clinician something concrete to open with, instead of a generic how-was-your-week question. Some clients rush through it; that itself is useful data about where their attention is. Keep it to the few minutes before the session properly begins, not as take-home work.', '[{"id": "f0", "type": "textarea", "label": "My mood right now, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "One word for this week"}, {"id": "f2", "type": "textarea", "label": "What I want to make sure we cover today"}, {"id": "f3", "type": "textarea", "label": "Anything since last time worth flagging"}]'::jsonb, array['session structure', 'monitoring']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('weekly-decision-log', 'Weekly Decision Log', 'worksheet'::resource_kind, 'A running log of decisions made over the week and the reasoning behind each one.', 'Use it to surface a client''s actual decision-making pattern over time.', array['Adults']::text[], 'Five minutes daily for one week', 'Each day the client notes one decision, big or small, what tipped it one way, and how sure they felt afterward. Reviewed together at the next session, the log tends to reveal a pattern, always deferring, always taking the fastest option, always asking three people first, that is easier to see written down across a week than described from memory in the room. Useful before targeting any specific decision difficulty.', '[{"id": "f0", "type": "textarea", "label": "Decision 1: what I chose and why"}, {"id": "f1", "type": "textarea", "label": "Decision 1: how sure I felt after, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Decision 2: what I chose and why"}, {"id": "f3", "type": "textarea", "label": "Decision 2: how sure I felt after, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "Decision 3: what I chose and why"}, {"id": "f5", "type": "textarea", "label": "Decision 3: how sure I felt after, 0 to 10"}, {"id": "f6", "type": "textarea", "label": "The pattern I noticed across the week"}]'::jsonb, array['decisions', 'self-monitoring', 'pattern']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('personal-rulebook-audit', 'Personal Rulebook Audit', 'worksheet'::resource_kind, 'A worksheet that lists a client''s unspoken personal rules and tests each one for flexibility.', 'Use it to make implicit personal rules explicit and open to question.', array['Adults', 'Teens']::text[], '20 minutes', 'Most people carry a private rulebook of always-and-never rules, always answer texts fast, never ask for help, always finish what''s started, that they''ve never written down or questioned. The client lists a handful, rates how rigid each feels, and picks one to loosen on purpose this week. This works well early in longer-term work as a map of where the pressure is coming from, before targeting any single belief directly.', '[{"id": "f0", "type": "textarea", "label": "A rule I live by that starts with \"always\" or \"never\""}, {"id": "f1", "type": "textarea", "label": "Where I think this rule came from"}, {"id": "f2", "type": "textarea", "label": "How rigid it feels, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What it costs me to keep it"}, {"id": "f4", "type": "textarea", "label": "One small way I could bend it this week"}]'::jsonb, array['core beliefs', 'standards']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('readiness-for-change-ruler', 'Readiness for Change Ruler', 'worksheet'::resource_kind, 'A simple 0-to-10 ruler for rating importance and confidence about a specific change.', 'Use it to locate where ambivalence about a change is actually coming from.', array['Adults', 'Teens']::text[], '10 minutes', 'The client rates a specific change on two separate rulers, how important it feels and how confident they are they could do it, then explains why they picked that number and not one lower. The why-not-lower question tends to surface existing motivation better than asking why not higher does. Low importance and low confidence point to different next conversations, so keep the two scores separate rather than averaging them.', '[{"id": "f0", "type": "textarea", "label": "The change I''m considering"}, {"id": "f1", "type": "textarea", "label": "How important this feels, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Why that number and not lower"}, {"id": "f3", "type": "textarea", "label": "How confident I am I could do it, 0 to 10"}, {"id": "f4", "type": "textarea", "label": "Why that number and not lower"}]'::jsonb, array['motivation', 'ambivalence', 'motivational interviewing']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('double-standard-technique', 'Double Standard Technique', 'cbt'::resource_kind, 'A worksheet that has the client answer their own harsh thought the way they''d answer a friend''s.', 'Use it to expose the gap between a client''s self-talk and their compassion for others.', array['Adults', 'Teens']::text[], '15 minutes', 'The client writes down a harsh self-judgment, then imagines a friend saying the exact same thing about themselves and writes the response they''d actually give that friend. Placed side by side, the gap between the two responses is usually obvious to the client without the clinician pointing it out. If the client''s answer to the friend is just as harsh, that''s useful information too, and worth exploring rather than treating as a failed exercise.', '[{"id": "f0", "type": "textarea", "label": "The harsh thought, exactly as it runs through my head"}, {"id": "f1", "type": "textarea", "label": "A friend who said this exact thing about themselves"}, {"id": "f2", "type": "textarea", "label": "What I would actually say back to that friend"}, {"id": "f3", "type": "textarea", "label": "How my two answers compare"}]'::jsonb, array['self-criticism', 'self-talk']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('problem-solving-steps-card', 'Problem-Solving Steps Card', 'cbt'::resource_kind, 'A step-by-step card that walks a client through defining a problem, weighing options, and picking one.', 'Use it to slow down problem-solving when a client is stuck cycling on one option.', array['Adults', 'Teens']::text[], '20 minutes', 'Many clients arrive at a problem already fixated on one solution or paralyzed between two. This card forces the sequence: state the problem in one plain sentence, list every option without judging it yet, rate each one quickly, then pick and schedule a first step. The brainstorming step is the one clients most want to skip; hold them to writing at least three options, even bad ones, before any rating happens.', '[{"id": "f0", "type": "textarea", "label": "The problem, in one plain sentence"}, {"id": "f1", "type": "textarea", "label": "Every option I can think of, judgment aside"}, {"id": "f2", "type": "textarea", "label": "A quick rating for each option, 1 to 5"}, {"id": "f3", "type": "textarea", "label": "The option I''m picking"}, {"id": "f4", "type": "textarea", "label": "My first step, and when I''ll take it"}]'::jsonb, array['problem solving', 'decisions']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('belief-certainty-thermometer', 'Belief Certainty Thermometer', 'cbt'::resource_kind, 'A rating scale that tracks how strongly a client believes a recurring thought before and after examining it.', 'Use it to track whether certainty in a recurring thought is actually shifting over time.', array['Adults', 'Teens']::text[], '10 minutes, repeated across sessions', 'Rather than working through the full evidence-gathering steps each time, this is a quick before-and-after number for a thought the client already knows well. It''s most useful once a specific thought has come up in a few sessions and the clinician wants a trend line rather than another full breakdown. A number that isn''t moving over several weeks is itself worth naming out loud with the client.', '[{"id": "f0", "type": "textarea", "label": "The recurring thought"}, {"id": "f1", "type": "textarea", "label": "How much I believe it right now, 0 to 100"}, {"id": "f2", "type": "textarea", "label": "One piece of evidence that complicates it"}, {"id": "f3", "type": "textarea", "label": "How much I believe it after considering that, 0 to 100"}]'::jsonb, array['thought record', 'automatic thoughts', 'core CBT']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('self-instructional-training-script', 'Self-Instructional Training Script', 'cbt'::resource_kind, 'A written script of coaching self-talk a client rehearses for a specific hard task, step by step.', 'Use it to build a rehearsed internal script for a task that usually triggers a freeze.', array['Adults', 'Teens', 'Children']::text[], '20 minutes to build, then practiced before the task', 'The client writes short coaching lines for themselves at each stage of a specific hard task, before starting, mid-task, if a mistake happens, and after finishing, in their own words rather than generic affirmations. Read it aloud together first; the wording only works if it sounds like the client''s own voice and not a script. This pairs well with something concrete and repeatable, like a phone call the client keeps avoiding.', '[{"id": "f0", "type": "textarea", "label": "The task this script is for"}, {"id": "f1", "type": "textarea", "label": "What I''ll say to myself before I start"}, {"id": "f2", "type": "textarea", "label": "What I''ll say to myself partway through"}, {"id": "f3", "type": "textarea", "label": "What I''ll say to myself if I make a mistake"}, {"id": "f4", "type": "textarea", "label": "What I''ll say to myself when it''s done"}]'::jsonb, array['self-talk', 'task initiation']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('point-counterpoint-thought-debate', 'Point-Counterpoint Thought Debate', 'cbt'::resource_kind, 'A written back-and-forth where the client argues both sides of a stuck negative thought in turn.', 'Use it to loosen a thought the client can state but can''t seem to argue with.', array['Adults', 'Teens']::text[], '20 minutes', 'The client writes one line arguing for the negative thought, then immediately one line arguing against it, alternating several rounds rather than writing a single list of evidence for each side. The back-and-forth rhythm tends to surface weaker arguments for the thought that a straight list doesn''t. Running it out loud in session first, with the clinician taking one side, gives the client a model before they try it alone on paper.', '[{"id": "f0", "type": "textarea", "label": "The thought we''re debating"}, {"id": "f1", "type": "textarea", "label": "Round 1 — for"}, {"id": "f2", "type": "textarea", "label": "Round 1 — against"}, {"id": "f3", "type": "textarea", "label": "Round 2 — for"}, {"id": "f4", "type": "textarea", "label": "Round 2 — against"}, {"id": "f5", "type": "textarea", "label": "Which side held up better, and why"}]'::jsonb, array['core CBT', 'automatic thoughts', 'thinking traps']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('values-vs-goals-sorting-cards', 'Values vs Goals Sorting Cards', 'act'::resource_kind, 'A sorting exercise that separates a client''s stated values from the specific goals attached to them.', 'Use it to untangle a value from the goal a client has been chasing in its name.', array['Adults', 'Teens']::text[], '20 minutes', 'The client writes down several things they''ve been striving toward, then sorts each one into a direction or a destination. A goal can be checked off; a value can''t, only lived. Clients who''ve stalled on an unreachable goal often discover the value underneath it is still fully available to act on today, even with the goal unmet. Keep the sorting concrete, real examples from their week, not abstractions.', '[{"id": "f0", "type": "textarea", "label": "Something I''ve been working toward"}, {"id": "f1", "type": "textarea", "label": "Is it a direction (ongoing) or a destination (checkable)?"}, {"id": "f2", "type": "textarea", "label": "The value underneath it"}, {"id": "f3", "type": "textarea", "label": "One way to live that value today, goal aside"}]'::jsonb, array['values', 'core ACT']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('value-action-gap-tracker', 'Value-Action Gap Tracker', 'act'::resource_kind, 'A short daily log comparing a client''s stated values to what they actually did that day.', 'Use it to make the gap between stated values and daily action visible over a week.', array['Adults', 'Teens']::text[], 'Five minutes daily for one week', 'Each evening the client names one value that mattered to them that day and rates, honestly, how much their actual behavior lined up with it. The point isn''t to produce a high score; a string of low ones is exactly the useful data. Bring the completed week into session and look for which value shows the widest gap, that''s usually the one worth building committed action around next.', '[{"id": "f0", "type": "textarea", "label": "A value that mattered today"}, {"id": "f1", "type": "textarea", "label": "How much my actions matched it, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What got in the way, if anything"}]'::jsonb, array['values', 'committed action']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('naming-the-story-practice', 'Naming the Story Practice', 'act'::resource_kind, 'A defusion exercise where a client gives a recurring thought pattern a short name to say instead of arguing with it.', 'Use it to give a client a fast way to notice a familiar thought pattern without engaging its content.', array['Adults', 'Teens']::text[], '10 minutes to build, then ongoing', 'Together, name a thought pattern that shows up often, the not-good-enough story, the running-late story, something short enough to say silently in the moment it appears. Practice catching it live in session first: when the thought shows up, the client says there''s the story instead of debating the content. This is defusion, not disagreement, so resist the urge to fact-check the story once it''s named; naming it is the whole move.', '[{"id": "f0", "type": "textarea", "label": "The recurring thought pattern"}, {"id": "f1", "type": "textarea", "label": "The short name we''re giving it"}, {"id": "f2", "type": "textarea", "label": "A moment this week I caught it and named it"}, {"id": "f3", "type": "textarea", "label": "What I did next instead of arguing with it"}]'::jsonb, array['defusion', 'core ACT']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('feared-and-wanted-self-compass', 'Feared and Wanted Self Compass', 'act'::resource_kind, 'A worksheet contrasting the person a client fears becoming with the person they want to become.', 'Use it to locate values by contrasting a feared future self with a wanted one.', array['Adults', 'Teens']::text[], '20 minutes', 'The client describes, in some detail, the person they''re afraid of becoming if things keep going the way they''re going, then does the same for the person they want to become. Values tend to surface more clearly in this contrast than they do from a straight what-matters-to-you question. Keep both descriptions concrete and specific rather than abstract traits, and end by naming one action this week that moves toward the wanted self.', '[{"id": "f0", "type": "textarea", "label": "The person I''m afraid of becoming"}, {"id": "f1", "type": "textarea", "label": "The person I want to become"}, {"id": "f2", "type": "textarea", "label": "The value that shows up in that contrast"}, {"id": "f3", "type": "textarea", "label": "One action this week toward the wanted self"}]'::jsonb, array['values', 'core ACT']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('function-over-form-card-sort', 'Function Over Form Card Sort', 'act'::resource_kind, 'A sorting exercise that classifies a client''s behaviors by what they accomplish, not what they look like.', 'Use it to help a client see that two very different behaviors can serve the same function.', array['Adults', 'Teens']::text[], '20 minutes', 'The client writes down several different behaviors from the week, some that look nothing alike on the surface, and sorts them by the function each one seems to serve: avoiding, connecting, numbing, controlling. Two behaviors that look opposite, like overworking and avoiding a task entirely, often land in the same pile once function is the sorting rule. This works well as a bridge into workability, once the pattern of function is visible on paper.', '[{"id": "f0", "type": "textarea", "label": "Behavior 1 and the function it seems to serve"}, {"id": "f1", "type": "textarea", "label": "Behavior 2 and the function it seems to serve"}, {"id": "f2", "type": "textarea", "label": "Behavior 3 and the function it seems to serve"}, {"id": "f3", "type": "textarea", "label": "Behaviors that ended up serving the same function"}]'::jsonb, array['workability', 'core ACT']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('interpersonal-effectiveness-priorities-sheet', 'Interpersonal Effectiveness Priorities Sheet', 'dbt'::resource_kind, 'A worksheet for ranking objective, relationship, and self-respect priorities before a hard conversation.', 'Use it to set clear priorities before scripting a request or a refusal.', array['Adults', 'Teens']::text[], '10 minutes', 'Before building a DEAR MAN script, the client ranks what matters most for this specific conversation: getting the outcome, protecting the relationship, or keeping self-respect intact. All three rarely rank equally, and knowing the order changes how firm or how soft the eventual script should be. This is a quick preparatory step, best done right before drafting the actual script rather than as a standalone exercise.', '[{"id": "f0", "type": "textarea", "label": "The conversation I''m preparing for"}, {"id": "f1", "type": "textarea", "label": "Rank: getting what I want"}, {"id": "f2", "type": "textarea", "label": "Rank: keeping the relationship steady"}, {"id": "f3", "type": "textarea", "label": "Rank: keeping my self-respect"}, {"id": "f4", "type": "textarea", "label": "What this ranking tells me about tone"}]'::jsonb, array['interpersonal effectiveness', 'DEAR MAN']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('both-and-language-swap', 'Both-And Language Swap', 'dbt'::resource_kind, 'A quick drill that has a client rewrite but-statements as and-statements to practice dialectical thinking.', 'Use it to practice holding two true things at once instead of picking one.', array['Adults', 'Teens']::text[], '10 minutes', 'The client writes a few sentences from the week that used but to pit two things against each other, I love them but I''m furious, and rewrites each one with and instead. The swap sounds small on paper but changes what the sentence is claiming: not a contradiction to resolve, but two things that are both true. Some clients resist the rewrite because it feels like letting themselves off the hook; that resistance is worth naming.', '[{"id": "f0", "type": "textarea", "label": "A \"but\" sentence from this week"}, {"id": "f1", "type": "textarea", "label": "The same sentence rewritten with \"and\""}, {"id": "f2", "type": "textarea", "label": "How the \"and\" version feels different to say"}]'::jsonb, array['dialectics', 'middle path']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('self-validation-practice-card', 'Self-Validation Practice Card', 'dbt'::resource_kind, 'A short practice for a client to validate their own reaction before deciding whether to act on it.', 'Use it to build the habit of validating a reaction before judging or acting on it.', array['Adults', 'Teens']::text[], 'Five minutes', 'Clients who are fluent at validating other people often skip the same step for themselves, moving straight from feeling to self-judgment. This card slows that down: name the reaction, find the piece of it that makes sense given the situation, say it back in plain language, and only then decide what, if anything, to do about it. Validating a reaction is not the same as agreeing it should drive the next action, and that distinction is worth making explicit.', '[{"id": "f0", "type": "textarea", "label": "What I felt or reacted with"}, {"id": "f1", "type": "textarea", "label": "What about this reaction makes sense, given the situation"}, {"id": "f2", "type": "textarea", "label": "Saying it back to myself in plain language"}, {"id": "f3", "type": "textarea", "label": "What I want to do about it, now that it''s validated"}]'::jsonb, array['validation', 'self-respect']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-stance-practice-card', 'Nonjudgmental Stance Practice Card', 'dbt'::resource_kind, 'A drill for rewriting a judgmental thought about a situation into a plain, factual description.', 'Use it to practice describing a situation before evaluating it as good or bad.', array['Adults', 'Teens']::text[], '10 minutes', 'The client writes a judgmental line from the week, that was a disaster, then rewrites it as a plain description of what actually happened, with no good, bad, should, or shouldn''t. Most clients find the factual version surprisingly hard to produce on the first try, which is itself worth naming. This is a rehearsal skill, best practiced on low-stakes moments before the client tries it on something that actually stung.', '[{"id": "f0", "type": "textarea", "label": "A judgmental sentence from this week"}, {"id": "f1", "type": "textarea", "label": "The same moment, described in plain facts only"}, {"id": "f2", "type": "textarea", "label": "Words I had to catch and remove"}, {"id": "f3", "type": "textarea", "label": "What shifted, if anything, once I reread the factual version"}]'::jsonb, array['mindfulness', 'core DBT']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('build-mastery-activity-planner', 'Build Mastery Activity Planner', 'dbt'::resource_kind, 'A weekly planner for scheduling one activity that builds a sense of competence and accomplishment.', 'Use it to schedule regular activities that build a sense of mastery, not just pleasant ones.', array['Adults', 'Teens']::text[], 'One week', 'Separate from pleasant activities, this planner schedules one thing per day that stretches the client slightly and leaves them with a sense of having accomplished something, a skill practiced, a task finished, a small challenge met. Difficulty should be chosen on purpose: too easy and it won''t register as mastery, too hard and it won''t get attempted. Review at the end of the week for which activities actually landed as a sense of competence.', '[{"id": "f0", "type": "textarea", "label": "Monday''s mastery activity"}, {"id": "f1", "type": "textarea", "label": "Tuesday''s mastery activity"}, {"id": "f2", "type": "textarea", "label": "Wednesday''s mastery activity"}, {"id": "f3", "type": "textarea", "label": "Thursday''s mastery activity"}, {"id": "f4", "type": "textarea", "label": "Friday''s mastery activity"}, {"id": "f5", "type": "textarea", "label": "Which ones actually felt like mastery, and why"}]'::jsonb, array['distress tolerance', 'habits']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('daily-temperature-reading', 'Daily Temperature Reading', 'couples'::resource_kind, 'A five-part structured check-in ritual couples run at home covering appreciations, updates, and hopes.', 'Use it to give a couple a low-stakes daily structure for actually talking to each other.', array['Couples']::text[], '15 minutes daily', 'Each partner takes a turn through five parts in order: something they appreciate about the other, new information about their day, anything confusing they want clarified, a complaint paired with what they''d want instead, and a hope for the future. The fixed order matters; appreciation always goes first, complaints are never allowed without a stated request attached. Couples who skip straight to the complaint step tend to recreate their usual fight, so hold them to starting with appreciation.', '[{"id": "f0", "type": "textarea", "label": "Partner A — something I appreciate about you"}, {"id": "f1", "type": "textarea", "label": "Partner B — something I appreciate about you"}, {"id": "f2", "type": "textarea", "label": "Partner A — a complaint and what I''d want instead"}, {"id": "f3", "type": "textarea", "label": "Partner B — a complaint and what I''d want instead"}, {"id": "f4", "type": "textarea", "label": "A hope we''re both naming for the future"}]'::jsonb, array['Gottman', 'communication', 'connection']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('curious-questions-interview-for-partners', 'Curious Questions Interview for Partners', 'couples'::resource_kind, 'A structured interview where each partner asks the other open questions and only reflects back, no responding.', 'Use it to practice curiosity between partners without either one defending or fixing.', array['Couples']::text[], '20 minutes', 'One partner asks a series of open questions about a topic, a stress, a hope, a past event, while the other answers; the asking partner''s only job is to reflect back what they heard, no advice, no rebuttal, no relating it to themselves. Switch roles halfway through. The hardest part for most partners is resisting the urge to jump in; if that happens, pause and name it rather than letting the interview turn into a normal back-and-forth conversation.', '[{"id": "f0", "type": "textarea", "label": "Partner A''s topic to be interviewed about"}, {"id": "f1", "type": "textarea", "label": "Questions Partner B asked"}, {"id": "f2", "type": "textarea", "label": "What Partner B reflected back"}, {"id": "f3", "type": "textarea", "label": "Partner B''s topic to be interviewed about"}, {"id": "f4", "type": "textarea", "label": "Questions Partner A asked"}, {"id": "f5", "type": "textarea", "label": "What Partner A reflected back"}]'::jsonb, array['listening', 'connection']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('conflict-de-escalation-signal-system', 'Conflict De-escalation Signal System', 'couples'::resource_kind, 'A worksheet where partners agree in advance on a shared signal to pause a conversation before it escalates.', 'Use it to build an agreed way to pause a conversation before it turns into a bigger fight.', array['Couples']::text[], '15 minutes', 'Built when both partners are calm, not mid-argument, this sets a specific word, gesture, or phrase either one can use to call a pause, plus what happens next, how long the pause lasts and who restarts the conversation. Vague agreements like just tell me to stop tend not to hold up under real heat; push for something oddly specific enough that it can''t be missed or mistaken for part of the argument itself.', '[{"id": "f0", "type": "textarea", "label": "Our agreed signal"}, {"id": "f1", "type": "textarea", "label": "How long the pause lasts once it''s called"}, {"id": "f2", "type": "textarea", "label": "What each of us does during the pause"}, {"id": "f3", "type": "textarea", "label": "Who restarts the conversation, and when"}]'::jsonb, array['de-escalation', 'conflict']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('money-conversation-starter-cards', 'Money Conversation Starter Cards', 'couples'::resource_kind, 'A set of low-pressure prompt cards that open up a couple''s talk about money and shared spending.', 'Use it to open a money conversation before it''s forced by a bill or a disagreement.', array['Couples']::text[], '20 minutes', 'Money conversations often only happen reactively, after a purchase or a bill has already caused friction. These cards give a couple a lower-stakes way in, questions about what money meant growing up, what feels safe versus risky, what a shared goal might look like, separate from any live disagreement. Run it on a calm evening, not right after a financial argument, and let each partner answer fully before moving to the next card.', '[{"id": "f0", "type": "textarea", "label": "What money meant in the home I grew up in"}, {"id": "f1", "type": "textarea", "label": "What makes me feel financially safe"}, {"id": "f2", "type": "textarea", "label": "What makes me feel financially anxious"}, {"id": "f3", "type": "textarea", "label": "A shared money goal I''d like us to have"}]'::jsonb, array['money', 'communication']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('shared-play-and-fun-inventory', 'Shared Play and Fun Inventory', 'couples'::resource_kind, 'A worksheet that maps out what counted as fun for a couple early on and what still does now.', 'Use it to rebuild a couple''s shared sense of play, not just their problem-solving.', array['Couples']::text[], '20 minutes', 'Couples often narrow down to logistics and repair work in sessions and lose track of whether they still have fun together at all. Each partner separately lists what used to be playful between them, what still is, and one small thing they''d like to try. Compare lists together; overlap is a good place to start scheduling something low-stakes this month, before tackling anything heavier in the next session.', '[{"id": "f0", "type": "textarea", "label": "Partner A — what used to be fun between us"}, {"id": "f1", "type": "textarea", "label": "Partner B — what used to be fun between us"}, {"id": "f2", "type": "textarea", "label": "What''s still fun now, for both of us"}, {"id": "f3", "type": "textarea", "label": "One new thing either of us would like to try"}]'::jsonb, array['connection', 'shared meaning']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('calm-down-corner-blueprint', 'Calm-Down Corner Blueprint', 'kids'::resource_kind, 'A drawing activity where a child designs their own calm-down spot at home, step by step.', 'Use it to give a child ownership over a specific calm-down space at home.', array['Children']::text[], '20 minutes', 'The child draws and labels a corner of a room, a beanbag, a soft light, a few chosen items, as their own calm-down spot, then the caregiver helps make it real at home that week. Having the child choose every item themselves matters more than how tidy or correct the drawing looks. Send the caregiver home with the plan and check in next session on whether the spot got built and used.', '[{"id": "f0", "type": "textarea", "label": "Where in our home this spot could be"}, {"id": "f1", "type": "textarea", "label": "What I want to have there"}, {"id": "f2", "type": "textarea", "label": "What I''ll do there when I''m upset"}, {"id": "f3", "type": "textarea", "label": "A name for my calm-down spot"}]'::jsonb, array['regulation', 'routines']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('feelings-traffic-light-craft', 'Feelings Traffic Light Craft', 'kids'::resource_kind, 'A craft where a child builds a traffic light and matches each color to a step for handling big feelings.', 'Use it to give a child a simple stop-think-go sequence for big feelings.', array['Children']::text[], '25 minutes', 'The child colors and cuts out a red, yellow, and green circle, then decides with the caregiver what each color means: red for stop and notice the feeling, yellow for a calming strategy, green for going back to what they were doing. Stick it somewhere visible at home so the caregiver can point to a color during a real moment instead of explaining the whole idea from scratch in the heat of it.', '[{"id": "f0", "type": "textarea", "label": "Red means... (stop and notice)"}, {"id": "f1", "type": "textarea", "label": "Yellow means... (a strategy I''ll try)"}, {"id": "f2", "type": "textarea", "label": "Green means... (back to what I was doing)"}, {"id": "f3", "type": "textarea", "label": "Where we''ll put my traffic light at home"}]'::jsonb, array['emotion regulation', 'regulation']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('coping-skills-robot-build', 'Coping Skills Robot Build', 'kids'::resource_kind, 'A craft where a child builds a paper robot with each body part standing for a different coping skill.', 'Use it to make a set of coping skills into something concrete a child can point to.', array['Children']::text[], '30 minutes', 'The child assembles a simple paper robot, and each part gets a job: the arms for a hug or squeeze, the lungs for slow breaths, the feet for a walk or stomp, the head for counting or naming colors in the room. Building it together in session lets the clinician check each skill actually makes sense to the child before it goes home. Encourage the caregiver to keep the robot somewhere the child can grab it fast.', '[{"id": "f0", "type": "textarea", "label": "What my robot''s arms do"}, {"id": "f1", "type": "textarea", "label": "What my robot''s lungs do"}, {"id": "f2", "type": "textarea", "label": "What my robot''s feet do"}, {"id": "f3", "type": "textarea", "label": "What my robot''s head does"}, {"id": "f4", "type": "textarea", "label": "My robot''s name"}]'::jsonb, array['emotion regulation', 'art']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('kindness-bingo-card', 'Kindness Bingo Card', 'kids'::resource_kind, 'A bingo card of small kind acts a child checks off across the week at home or school.', 'Use it to build a habit of noticing and doing small kind acts.', array['Children']::text[], 'One week', 'Fill the grid together with small, doable kind acts sized to the child, holding a door, sharing a toy, checking on a sad friend, and let the child color a square each time one happens, with the caregiver helping notice and log it that day. A full card isn''t the point; a couple of squares filled by next session is still worth celebrating and naming out loud in the room.', '[{"id": "f0", "type": "textarea", "label": "Square 1"}, {"id": "f1", "type": "textarea", "label": "Square 2"}, {"id": "f2", "type": "textarea", "label": "Square 3"}, {"id": "f3", "type": "textarea", "label": "Square 4"}, {"id": "f4", "type": "textarea", "label": "Which one felt best to do"}]'::jsonb, array['kindness', 'habits']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('playdough-feelings-sculpt', 'Playdough Feelings Sculpt', 'kids'::resource_kind, 'A sensory activity where a child sculpts a feeling out of playdough and talks about its shape and texture.', 'Use it to give a child a hands-on way into naming a feeling they can''t yet put into words.', array['Children']::text[], '20 minutes', 'Some children can shape a feeling before they can name it. Hand over playdough and ask them to make what a feeling looks like, big or small, spiky or smooth, one color or several, then talk through the choices they made rather than asking directly what does this mean. Keep the questions about the sculpture itself; naming the feeling often follows on its own once the child has something in their hands to point to.', '[{"id": "f0", "type": "textarea", "label": "What feeling I sculpted"}, {"id": "f1", "type": "textarea", "label": "Why I made it this shape"}, {"id": "f2", "type": "textarea", "label": "Why I picked this color"}, {"id": "f3", "type": "textarea", "label": "What I''d change if I made it again"}]'::jsonb, array['emotion identification', 'sensory']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('find-someone-who-icebreaker', 'Find Someone Who Icebreaker', 'game'::resource_kind, 'A mingling group game where members find who among them matches each prompt on a card.', 'Use it to open a new group with low-stakes mingling before deeper sharing starts.', array['Groups', 'Teens', 'Adults']::text[], '15 minutes', 'Each member gets a card with several prompts, like find someone who has a pet, or find someone who''s tried a coping skill this week, and mingles to fill in a name next to each one before time runs out. Keep the prompts light for a brand-new group and save anything more personal for later sessions once trust has built. Debrief by asking what surprised them or what they have in common with someone they didn''t expect.', '[{"id": "f0", "type": "textarea", "label": "Prompt 1 and who matched it"}, {"id": "f1", "type": "textarea", "label": "Prompt 2 and who matched it"}, {"id": "f2", "type": "textarea", "label": "Prompt 3 and who matched it"}, {"id": "f3", "type": "textarea", "label": "Something that surprised me"}, {"id": "f4", "type": "textarea", "label": "Debrief: what did this feel like to do?"}]'::jsonb, array['icebreaker', 'group']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('musical-chairs-check-in-game', 'Musical Chairs Check-In Game', 'game'::resource_kind, 'A group game where the music stopping cues a quick check-in prompt for whoever''s nearest a chair.', 'Use it to break up a long group session with a light, moving check-in.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'Set up a chair for everyone, no elimination, and play music while the group moves around; when it stops, whoever''s nearest a marked chair answers a quick check-in prompt pulled from a stack before the music starts again. Skip the usual elimination rule so nobody sits out; the point is the movement and the prompt, not a winner. Debrief afterward on which prompt was hardest to answer out loud.', '[{"id": "f0", "type": "textarea", "label": "Prompt drawn, round 1"}, {"id": "f1", "type": "textarea", "label": "My answer, round 1"}, {"id": "f2", "type": "textarea", "label": "Prompt drawn, round 2"}, {"id": "f3", "type": "textarea", "label": "My answer, round 2"}, {"id": "f4", "type": "textarea", "label": "Debrief: which prompt was hardest to answer?"}]'::jsonb, array['group', 'icebreaker']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('four-corners-opinion-game', 'Four Corners Opinion Game', 'game'::resource_kind, 'A group game where members move to a room corner matching how strongly they agree with a statement.', 'Use it to make a group''s range of opinions visible and open a discussion from there.', array['Groups', 'Teens']::text[], '20 minutes', 'Label four corners of the room strongly agree, agree, disagree, and strongly disagree, read a statement aloud, and have everyone move to the corner that fits before any discussion starts. Once everyone''s placed, ask a few people in different corners to explain their spot. Statements work best when there''s no clear right answer; pull from the group''s own week rather than abstract debate topics.', '[{"id": "f0", "type": "textarea", "label": "Statement 1 and my corner"}, {"id": "f1", "type": "textarea", "label": "Why I picked that corner"}, {"id": "f2", "type": "textarea", "label": "Statement 2 and my corner"}, {"id": "f3", "type": "textarea", "label": "Why I picked that corner"}, {"id": "f4", "type": "textarea", "label": "Debrief: what did I notice about the group''s spread?"}]'::jsonb, array['group', 'perspective']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('trust-walk-game', 'Trust Walk Game', 'game'::resource_kind, 'A paired game where one partner guides the other, eyes closed, through a safe space using only words.', 'Use it to build a concrete, felt sense of trust between two people through a shared task.', array['Couples', 'Groups', 'Teens']::text[], '15 minutes', 'One person closes their eyes while their partner guides them slowly through a cleared, safe space using only spoken directions, no touching unless agreed beforehand. Switch roles after a few minutes. Keep the space genuinely obstacle-free and check in before starting about what kind of guidance actually feels helpful versus overwhelming. Debrief on what it was like to depend on someone else''s words alone.', '[{"id": "f0", "type": "textarea", "label": "What it felt like to be guided"}, {"id": "f1", "type": "textarea", "label": "What it felt like to guide"}, {"id": "f2", "type": "textarea", "label": "A moment I felt most trusting"}, {"id": "f3", "type": "textarea", "label": "Debrief: what made this easier or harder than expected?"}]'::jsonb, array['trust', 'connection']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('coping-skills-speed-match', 'Coping Skills Speed Match', 'game'::resource_kind, 'A timed team game matching coping-skill cards to scenario cards before the clock runs out.', 'Use it to make recalling and matching coping skills to situations faster and more automatic.', array['Groups', 'Teens', 'Children']::text[], '15 minutes', 'Split into small teams, each with a stack of coping-skill cards and a stack of scenario cards; on go, teams race to pair each scenario with a skill that could plausibly help before time runs out. There''s rarely one right answer, so score for a reasonable match explained out loud rather than a fixed answer key. Debrief on which scenario was hardest to match and why.', '[{"id": "f0", "type": "textarea", "label": "A scenario and skill we matched"}, {"id": "f1", "type": "textarea", "label": "Our reasoning for that match"}, {"id": "f2", "type": "textarea", "label": "The hardest scenario to match"}, {"id": "f3", "type": "textarea", "label": "Debrief: what made that one harder?"}]'::jsonb, array['skills', 'group']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('end-of-session-grounding-checklist', 'End-of-Session Grounding Checklist', 'worksheet'::resource_kind, 'A short checklist to confirm a client is grounded and safe before they leave a trauma-focused session.', 'Use it to make sure a client leaves session regulated, not raw, after trauma-focused work.', array['Adults', 'Teens']::text[], 'Five minutes at the end of session', 'Run through this checklist at the close of any session that touched trauma-related material: check the client''s current arousal level, orient them to where they are and what day it is, confirm a support plan for the next few hours, and name one grounding skill they''ll use if activated later. Watch for clients who try to rush out the door once the clock runs low; slow the close down deliberately and treat it as part of the session, not an optional extra.', '[{"id": "f0", "type": "textarea", "label": "My body''s activation level right now, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "Where I am and what day and time it is"}, {"id": "f2", "type": "textarea", "label": "One person or place I can go if I need support in the next few hours"}, {"id": "f3", "type": "textarea", "label": "The grounding skill I''ll use if I feel activated later"}, {"id": "f4", "type": "textarea", "label": "One thing I notice in this room that reminds me I''m here, not there"}]'::jsonb, array['PTSD and trauma', 'grounding', 'session structure', 'pacing']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('anniversary-reaction-planner', 'Anniversary Reaction Planner', 'worksheet'::resource_kind, 'A forward-looking plan for the dates and seasons that tend to stir up a trauma anniversary reaction.', 'Use it to help a client line up support and pacing before a known hard date arrives.', array['Adults', 'Teens']::text[], '20 minutes, revisited yearly', 'Talk with the client about which dates or seasons tend to bring a spike in symptoms, then build a plan for that window: who they''ll tell ahead of time, what they''ll lighten on their calendar, and which grounding or support step they''ll lean on if the day gets hard. This is planning, not processing, so keep the focus on logistics and support rather than on retelling events from the past. Revisit and update the plan each year, since the dates or the needs around them can shift.', '[{"id": "f0", "type": "textarea", "label": "Dates or seasons that tend to be harder for me"}, {"id": "f1", "type": "textarea", "label": "Who I''ll let know ahead of time"}, {"id": "f2", "type": "textarea", "label": "What I''ll lighten or move on my calendar that week"}, {"id": "f3", "type": "textarea", "label": "My grounding or support step if the day gets hard"}, {"id": "f4", "type": "textarea", "label": "One kind thing I''ll plan for myself that day"}]'::jsonb, array['PTSD and trauma', 'safety planning', 'pacing']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('then-vs-now-safety-check', 'Then vs Now Safety Check', 'cbt'::resource_kind, 'A present-moment check comparing an old alarm reaction to the actual safety of right now.', 'Use it to help a client notice when a threat alarm is firing from then, not now.', array['Adults', 'Teens']::text[], 'Ten minutes, as needed', 'When a client notices their body sounding an alarm, walk them through naming the sensation, then checking concrete present-moment evidence: where they are, who is with them, and what is actually happening right now, separate from what the alarm seems to be warning about. The point isn''t to argue the alarm away but to give the client a quick, repeatable way to orient to the present when an old reaction fires in a safe context. Keep it brief and concrete; this is a present-tense check, never a place to write out the original event.', '[{"id": "f0", "type": "textarea", "label": "What my body is doing right now"}, {"id": "f1", "type": "textarea", "label": "What the alarm seems to be warning me about"}, {"id": "f2", "type": "textarea", "label": "Where I actually am right now"}, {"id": "f3", "type": "textarea", "label": "Who is actually with me right now"}, {"id": "f4", "type": "textarea", "label": "What''s actually true about my safety in this moment"}]'::jsonb, array['PTSD and trauma', 'grounding', 'automatic thoughts']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-card', 'IMPROVE the Moment Card', 'dbt'::resource_kind, 'A card walking through the DBT IMPROVE skills for getting through an overwhelming moment safely.', 'Use it to give a client a menu of ways to make a hard moment more bearable without escalating.', array['Adults', 'Teens']::text[], 'Ongoing, five minutes per use', 'Walk the client through the IMPROVE letters, imagery, meaning, one thing at a time, a brief mental vacation, encouragement, and relaxation, and have them mark which ones tend to actually work for their body. Some clients gravitate to one or two letters and never touch the rest, which is fine; the point is a short list they can reach for fast rather than working every letter every time. Practice one or two in session before sending the card home, so the client has felt it work at least once.', '[{"id": "f0", "type": "textarea", "label": "Imagery: a calm scene I can picture"}, {"id": "f1", "type": "textarea", "label": "Meaning: something that helps this moment make sense"}, {"id": "f2", "type": "textarea", "label": "One thing: what I''ll focus on right now, just this"}, {"id": "f3", "type": "textarea", "label": "Vacation: a short mental break I can take"}, {"id": "f4", "type": "textarea", "label": "Encouragement: what I can say to myself"}, {"id": "f5", "type": "textarea", "label": "Relaxation: what helps my body loosen"}]'::jsonb, array['PTSD and trauma', 'distress tolerance', 'core DBT']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('safety-signal-system-for-couples', 'Safety Signal System for Couples', 'couples'::resource_kind, 'A private signal partner A can give when triggered, and a calm response plan for partner B.', 'Use it to help a couple respond to trauma triggers with pacing instead of confusion or panic.', array['Couples']::text[], '30 minutes to set up, then ongoing', 'Partner A picks a simple word or gesture to signal feeling triggered or overwhelmed, something easy to use even while flooded. Partner B agrees on a short, predictable response: give space, lower their voice, and stay nearby without pressing for an explanation. Build the plan together in session so neither partner is guessing later, and practice the signal once while both are calm. This is a pacing tool for the moment, not a prompt for either partner to explain or relive what happened.', '[{"id": "f0", "type": "textarea", "label": "Partner A''s signal word or gesture"}, {"id": "f1", "type": "textarea", "label": "What partner B does when the signal is given"}, {"id": "f2", "type": "textarea", "label": "What partner A needs in the minutes right after"}, {"id": "f3", "type": "textarea", "label": "A follow-up check-in the two of us can use later that day"}]'::jsonb, array['PTSD and trauma', 'relationships', 'safety planning']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('what-if-spiral-tracker', 'What-If Spiral Tracker', 'worksheet'::resource_kind, 'A worksheet for tracing a chain of what-if thoughts to find where the spiral can be interrupted.', 'Use it to help a client see the shape of a worry spiral instead of getting lost inside it.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client write the first what-if that started a spiral, then the next thought it led to, and the next, until the chain runs out or gets too big to keep writing. Reading the chain back usually shows how far the mind traveled from the original, small trigger. Ask where in the chain the client could realistically interrupt the spiral next time, often earlier than they''d expect, and circle that link as the target for practice.', '[{"id": "f0", "type": "textarea", "label": "The first what-if that started it"}, {"id": "f1", "type": "textarea", "label": "What it led to next"}, {"id": "f2", "type": "textarea", "label": "And then what it led to after that"}, {"id": "f3", "type": "textarea", "label": "Where I could interrupt this chain next time"}]'::jsonb, array['anxiety', 'worry', 'thought record']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('probability-overestimation-log', 'Probability Overestimation Log', 'cbt'::resource_kind, 'A log comparing a client''s predicted odds of a feared outcome against what actually happened.', 'Use it to correct a pattern of overestimating how likely a feared outcome really is.', array['Adults', 'Teens']::text[], 'One to two weeks', 'Before a feared situation, have the client write down what they think will happen and their percentage estimate that it will. Afterward, they record what actually happened and re-rate it in hindsight. Most clients with anxiety consistently overestimate the odds; seeing the gap in their own numbers across several entries tends to land harder than being told the odds are lower. Review the pattern together after a week or two rather than pointing it out after a single entry.', '[{"id": "f0", "type": "textarea", "label": "The situation I''m predicting"}, {"id": "f1", "type": "textarea", "label": "What I think will happen"}, {"id": "f2", "type": "textarea", "label": "My percent estimate it will happen"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "My estimate now, looking back"}]'::jsonb, array['anxiety', 'evidence log', 'automatic thoughts']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('anxious-mind-radio-station', 'Anxious Mind Radio Station', 'act'::resource_kind, 'A defusion exercise imagining anxious thoughts as a radio station playing in the background.', 'Use it to help a client notice anxious thoughts without treating each one as an announcement.', array['Adults', 'Teens']::text[], 'Ten minutes, then as needed', 'Ask the client to name their anxious inner voice as a radio station, something like Worry FM, that plays whether or not anyone is tuned in. Practice noticing when the station comes on, naming it out loud, Worry FM again, and choosing whether to turn the volume up or let it play in the background while attention goes elsewhere. The goal isn''t to turn the station off; it''s to change the client''s relationship to a broadcast that used to feel like the only channel available.', '[{"id": "f0", "type": "textarea", "label": "What Worry FM tends to play"}, {"id": "f1", "type": "textarea", "label": "When I noticed it come on this week"}, {"id": "f2", "type": "textarea", "label": "What I did instead of turning the volume up"}, {"id": "f3", "type": "textarea", "label": "What I was able to keep doing with it playing in the background"}]'::jsonb, array['anxiety', 'defusion', 'core ACT']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('nonjudgmental-anxiety-narration-card', 'Nonjudgmental Anxiety Narration Card', 'dbt'::resource_kind, 'Practice describing anxious thoughts and sensations in plain facts, without judgment words attached.', 'Use it to help a client separate raw anxious experience from the judgments piled on top.', array['Adults', 'Teens']::text[], 'Ten minutes', 'Have the client describe an anxious moment twice: first in their usual language, then again using only observable facts, what the body did, what the thought said, with no words like terrible, stupid, or awful attached. Most clients are surprised how much of their distress comes from the judgment layer rather than the raw sensation underneath it. This is a describing practice, not a debate about whether the anxiety is justified.', '[{"id": "f0", "type": "textarea", "label": "The anxious moment, in my usual words"}, {"id": "f1", "type": "textarea", "label": "The same moment, just the facts, no judgment words"}, {"id": "f2", "type": "textarea", "label": "What changed between the two versions"}, {"id": "f3", "type": "textarea", "label": "A judgment word I catch myself using often"}]'::jsonb, array['anxiety', 'core DBT', 'self-talk']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('worry-detective-badge-kit', 'Worry Detective Badge Kit', 'kids'::resource_kind, 'A pretend-detective kit for kids to investigate what their worry is trying to warn them about.', 'Use it to help a child feel curious about worry instead of only scared of it.', array['Children']::text[], '20 minutes, then ongoing', 'The child becomes a Worry Detective with a badge and a notebook, investigating one worry at a time: what clue tipped them off that worry showed up, what the worry seems to be trying to protect them from, and one brave step to test it out. The caregiver plays sidekick, asking questions rather than answering for the child, and a badge sticker is earned for each brave step attempted, whether or not it goes well. If a child discloses something concerning during the investigation, the clinician''s reporting duties apply.', '[{"id": "f0", "type": "textarea", "label": "What clue told me worry showed up"}, {"id": "f1", "type": "textarea", "label": "What my worry might be trying to protect me from"}, {"id": "f2", "type": "textarea", "label": "One brave step I could test"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it"}]'::jsonb, array['anxiety', 'children', 'externalizing']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('good-enough-task-tiers', 'Good Enough Task Tiers', 'worksheet'::resource_kind, 'A worksheet breaking one task into a bare-minimum, better, and best version for low-energy days.', 'Use it to help a client finish something on a low day instead of freezing over the ideal version.', array['Adults', 'Teens']::text[], 'Ten minutes', 'For one task the client keeps avoiding, help them write three versions: the bare minimum that still counts, a better version if there''s a bit more energy, and the best version if the day allows it. On a low-energy day the client is only asked to hit the bare minimum tier, no apology needed. This breaks the all-or-nothing pattern where a task feels pointless unless done fully, which for many low-mood clients means it never gets started at all.', '[{"id": "f0", "type": "textarea", "label": "The task"}, {"id": "f1", "type": "textarea", "label": "Bare minimum version that still counts"}, {"id": "f2", "type": "textarea", "label": "Better version, if there''s more energy"}, {"id": "f3", "type": "textarea", "label": "Best version, if the day allows it"}, {"id": "f4", "type": "textarea", "label": "Which tier I actually did"}]'::jsonb, array['depression', 'task initiation', 'behavioral activation']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('anticipated-vs-actual-enjoyment-log', 'Anticipated vs Actual Enjoyment Log', 'cbt'::resource_kind, 'A log comparing how much enjoyment a client predicts from an activity against what they actually felt.', 'Use it to correct the low-mood prediction that nothing will feel worth doing.', array['Adults', 'Teens']::text[], 'One to two weeks', 'Before an activity, the client rates how much they expect to enjoy it. Right after, they rate what they actually felt. Low mood tends to predict flat or negative in advance and undersell what actually happened, and clients rarely notice the gap unless it''s written down side by side. Use a run of entries, not just one, to make the pattern visible, and prompt the client to choose the next activity based on the log rather than the prediction.', '[{"id": "f0", "type": "textarea", "label": "The activity"}, {"id": "f1", "type": "textarea", "label": "Predicted enjoyment, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Actual enjoyment, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What surprised me, if anything"}]'::jsonb, array['depression', 'behavioral activation', 'evidence log']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('depression-story-sort', 'The Depression Story Sort', 'act'::resource_kind, 'A card sort separating the running story low mood tells from the plain facts of the day.', 'Use it to loosen the grip of a fixed low-mood narrative on how a client reads their own day.', array['Adults', 'Teens']::text[], '20 minutes', 'Write out a handful of statements from the client''s inner narrative, such as I never do anything right or nothing will change, on separate cards, then sort them into two piles: story and fact. A fact has to be something a video camera could have recorded; a story is interpretation, however familiar it feels. Most cards land in the story pile, which is the point, not to prove the story wrong, but to show the client it''s a story they''re carrying, not a verdict.', '[{"id": "f0", "type": "textarea", "label": "A statement my mind tells me on hard days"}, {"id": "f1", "type": "textarea", "label": "Is it a fact a camera could record, or a story?"}, {"id": "f2", "type": "textarea", "label": "What the camera would have actually recorded"}, {"id": "f3", "type": "textarea", "label": "What I notice calling it a story instead of a verdict"}]'::jsonb, array['depression', 'defusion', 'self-as-context']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('behavioral-activation-dice-game', 'Behavioral Activation Dice Game', 'game'::resource_kind, 'A dice game that picks a category of small activity to do right now, with a debrief question after.', 'Use it to lower the barrier to starting an activity when motivation is too low to choose one.', array['Adults', 'Teens', 'Groups']::text[], '15 minutes', 'Label six dice faces with categories, movement, connection, self-care, mastery, novelty, and rest, and have the client roll. Whatever comes up, they commit to one small action in that category within the next ten minutes, in session if possible. After trying it, ask the debrief question: what changed, even slightly, in mood or energy, once they did it? The game removes the paralysis of choosing among options by making the choice random and small.', '[{"id": "f0", "type": "textarea", "label": "What the die landed on"}, {"id": "f1", "type": "textarea", "label": "The small action I chose in that category"}, {"id": "f2", "type": "textarea", "label": "Debrief: what changed, even slightly, after I did it"}]'::jsonb, array['depression', 'behavioral activation', 'motivation']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('daily-mastery-builder-card', 'Daily Mastery Builder Card', 'dbt'::resource_kind, 'A daily card for choosing one small task to complete competently, to counter feelings of helplessness.', 'Use it to rebuild a sense of competence one small completed task at a time.', array['Adults', 'Teens']::text[], 'Five minutes daily for two weeks', 'Each day, the client picks one task slightly on the easier side of their ability and does it as well as they reasonably can, then notes it on the card. The task should be small enough to actually finish, organizing one drawer, replying to one message, not a project. This DBT mastery skill works against the helplessness that low mood builds by giving the client daily, countable proof that they can still do something well, however small.', '[{"id": "f0", "type": "textarea", "label": "Today''s task"}, {"id": "f1", "type": "textarea", "label": "Did I complete it?"}, {"id": "f2", "type": "textarea", "label": "How it went"}, {"id": "f3", "type": "textarea", "label": "What this tells me about what I can still do"}]'::jsonb, array['depression', 'core DBT', 'self-respect']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('transition-countdown-planner', 'Transition Countdown Planner', 'worksheet'::resource_kind, 'A worksheet for building a warning countdown before a hard task switch instead of a sudden stop.', 'Use it to make transitions between tasks less likely to trigger resistance or a meltdown.', array['Adults', 'Teens', 'Children']::text[], '15 minutes to set up', 'Map out a transition that reliably goes badly, screen time to homework, play to bedtime, and build a countdown around it: a warning at ten minutes, five minutes, and two minutes, each with a specific phrase or signal rather than a vague almost time. Add one small bridge activity between the two tasks, like a two-minute stretch, so the switch isn''t abrupt. Adjust the countdown length based on what the client actually needs, not what seems reasonable on paper.', '[{"id": "f0", "type": "textarea", "label": "The transition that goes badly"}, {"id": "f1", "type": "textarea", "label": "Ten-minute warning phrase or signal"}, {"id": "f2", "type": "textarea", "label": "Five-minute warning"}, {"id": "f3", "type": "textarea", "label": "Two-minute warning"}, {"id": "f4", "type": "textarea", "label": "Bridge activity between the two tasks"}]'::jsonb, array['ADHD', 'transitions', 'executive function']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('executive-function-self-talk-rewrite', 'Executive Function Self-Talk Rewrite', 'cbt'::resource_kind, 'A thought record rewriting self-critical labels about forgetfulness into function-based language.', 'Use it to replace lazy self-talk with language that points to a fixable executive function gap.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client write the harsh label that shows up after a missed deadline or forgotten task, lazy, careless, broken, next to what actually happened in executive function terms: a working-memory slip, a planning gap, a time-blindness moment. Rewriting the event in function language doesn''t excuse the impact, but it opens up a fixable next step instead of a character verdict the client can''t act on. Keep a running list of these rewrites to spot the client''s most common gap.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "The harsh label that showed up"}, {"id": "f2", "type": "textarea", "label": "The executive function gap underneath it"}, {"id": "f3", "type": "textarea", "label": "One concrete next step that addresses the gap"}]'::jsonb, array['ADHD', 'executive function', 'self-talk']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('body-battery-check-in-cards', 'Body Battery Check-In Cards', 'kids'::resource_kind, 'Cards a child uses to show their energy and focus level as a battery icon throughout the day.', 'Use it to help a child and caregiver notice a low-focus dip before it turns into a meltdown.', array['Children']::text[], 'Five minutes, several times a day', 'Give the child a set of battery cards from full to empty and have them pick one at set check-in points, after school, before homework, before bed. A caregiver keeps the check-ins short and judgment-free; the point is information, not a report card. A pattern of afternoon empties, for example, might mean homework moves earlier or a movement break gets built in first. Track the pattern for a week before making changes based on it.', '[{"id": "f0", "type": "textarea", "label": "Morning battery level"}, {"id": "f1", "type": "textarea", "label": "After school battery level"}, {"id": "f2", "type": "textarea", "label": "Before homework battery level"}, {"id": "f3", "type": "textarea", "label": "Before bed battery level"}, {"id": "f4", "type": "textarea", "label": "What helped recharge it today"}]'::jsonb, array['ADHD', 'children', 'executive function']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('focus-relay-race', 'Focus Relay Race', 'game'::resource_kind, 'A turn-based relay game where each player beats a short timer on one small focus task.', 'Use it to practice short bursts of sustained focus in a format that feels playful, not draining.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Set a short timer, ninety seconds works well, and have each player complete one small task before it runs out, sorting cards, a simple puzzle piece, a short copying task, then pass to the next player. Keep tasks genuinely short so success is likely and the timer creates mild urgency rather than pressure. After each round, ask the debrief question: what helped you stay with it for those ninety seconds? Adjust task difficulty and timer length to keep it winnable.', '[{"id": "f0", "type": "textarea", "label": "My task this round"}, {"id": "f1", "type": "textarea", "label": "Did I beat the timer?"}, {"id": "f2", "type": "textarea", "label": "Debrief: what helped me stay with it"}]'::jsonb, array['ADHD', 'attention', 'executive function']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('adhd-teamwork-task-map', 'ADHD Teamwork Task Map', 'couples'::resource_kind, 'A map for splitting household follow-through so neither partner ends up as the default rememberer.', 'Use it to turn follow-through gaps into a shared system instead of a blame cycle.', array['Couples']::text[], '30 minutes', 'Have partner A and partner B list the recurring tasks that tend to get dropped, then sort each one by who''s better positioned to own the reminder system for it, not who should remember, but who has a system that actually works for them, like an alarm or a visible list. The partner without ADHD names what support looks like without turning into a reminder service; the partner with ADHD names what kind of reminder actually lands. Revisit the map monthly since what works tends to drift.', '[{"id": "f0", "type": "textarea", "label": "Task that keeps getting dropped"}, {"id": "f1", "type": "textarea", "label": "Who owns the reminder system for it"}, {"id": "f2", "type": "textarea", "label": "What kind of reminder actually works for that partner"}, {"id": "f3", "type": "textarea", "label": "What support from the other partner looks like, without nagging"}]'::jsonb, array['ADHD', 'relationships', 'executive function']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('high-risk-situation-planner', 'High-Risk Situation Planner', 'worksheet'::resource_kind, 'A worksheet for mapping upcoming situations likely to raise urges and planning for each one ahead of time.', 'Use it to help a client prepare for risky situations before urges show up, not during them.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client list specific situations coming up in the next week or month that have raised urges around substance use before, a certain event, a certain person, a certain time of day, and for each one, write a concrete plan: who they''ll go with, what they''ll say if offered, and an exit option if it gets hard. Planning ahead of time, while the urge isn''t active, tends to produce steadier answers than trying to think clearly in the moment. Review the plans together before the situation arrives.', '[{"id": "f0", "type": "textarea", "label": "The upcoming situation"}, {"id": "f1", "type": "textarea", "label": "What tends to raise urges about it"}, {"id": "f2", "type": "textarea", "label": "My plan going in"}, {"id": "f3", "type": "textarea", "label": "What I''ll say if offered"}, {"id": "f4", "type": "textarea", "label": "My exit option if it gets hard"}]'::jsonb, array['addiction', 'urges', 'relapse prevention']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('urge-thought-record', 'Urge Thought Record', 'cbt'::resource_kind, 'A thought record capturing the automatic thought that shows up right before an urge to use.', 'Use it to test the automatic beliefs that make an urge feel more urgent than it is.', array['Adults', 'Teens']::text[], 'Ongoing, five minutes per entry', 'When an urge tied to substance use shows up, have the client write the automatic thought that came with it, often something like I can''t handle this or just this once won''t matter, rate how much they believed it in the moment, and later, once the urge has passed, rate it again with some distance. Reviewing a run of entries usually shows the belief was more convincing during the urge than it looks afterward, which is useful evidence for the next one.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The automatic thought that came with the urge"}, {"id": "f2", "type": "textarea", "label": "How much I believed it in the moment, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "How much I believe it now, looking back"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}]'::jsonb, array['addiction', 'urges', 'automatic thoughts']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('urge-willingness-scale', 'Urge Willingness Scale', 'act'::resource_kind, 'A practice for rating willingness to feel an urge without acting on it, tracked across a scale.', 'Use it to build a client''s capacity to feel an urge fully without needing it to go away first.', array['Adults', 'Teens']::text[], 'Ten minutes, as needed', 'When an urge tied to substance use shows up, have the client rate two things side by side: how strong the urge feels, and how willing they are to let it be there without acting on it, both on a zero to ten scale. The goal isn''t to force willingness to ten; it''s to notice that the two numbers can move independently of each other, and that willingness tends to rise with practice even when urge intensity doesn''t drop. Track a few entries together to make the pattern visible.', '[{"id": "f0", "type": "textarea", "label": "Urge intensity, 0 to 10"}, {"id": "f1", "type": "textarea", "label": "My willingness to feel it without acting, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What I did instead"}, {"id": "f3", "type": "textarea", "label": "What I noticed about the two numbers"}]'::jsonb, array['addiction', 'urges', 'willingness']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('dialectical-abstinence-planner', 'Dialectical Abstinence Planner', 'dbt'::resource_kind, 'A DBT-informed plan holding both a full commitment to stop and a real plan for what happens after a lapse.', 'Use it to help a client commit fully to change without abandoning the effort after one lapse.', array['Adults', 'Teens']::text[], '20 minutes, revisited as needed', 'Have the client write their full commitment to stopping substance use in their own words, then, on the same page, write a specific plan for what they''ll do in the first hour after an urge wins out and a lapse happens, who they''ll call, what they won''t do, how they''ll get back to the commitment. Holding both at once, total commitment and a real lapse plan, is the dialectical move: it removes the all-or-nothing trap where one slip to an urge reads as total failure and the whole effort gets dropped.', '[{"id": "f0", "type": "textarea", "label": "My commitment, in my own words"}, {"id": "f1", "type": "textarea", "label": "My plan for the first hour after a lapse, if one happens"}, {"id": "f2", "type": "textarea", "label": "Who I''ll call"}, {"id": "f3", "type": "textarea", "label": "How I''ll get back to the commitment"}]'::jsonb, array['addiction', 'core DBT', 'relapse prevention']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('support-vs-enabling-conversation-map', 'Support vs Enabling Conversation Map', 'couples'::resource_kind, 'A guide helping both partners sort which supportive habits help recovery and which quietly enable use.', 'Use it to help a couple tell genuine support apart from patterns that protect substance use.', array['Couples']::text[], '30 minutes', 'Have partner A, the partner working on substance use, and partner B, the supporting partner, each list things partner B currently does to help, then sort the list together into support and enabling, covering for missed commitments versus letting natural consequences land when an urge wins out, for example. This conversation tends to bring up guilt on both sides, so keep the tone toward the shared goal rather than blame. Agree on one or two changes to try for a couple of weeks, not a full overhaul at once.', '[{"id": "f0", "type": "textarea", "label": "Something partner B currently does to help"}, {"id": "f1", "type": "textarea", "label": "Support or enabling?"}, {"id": "f2", "type": "textarea", "label": "One change we''ll try for the next two weeks"}, {"id": "f3", "type": "textarea", "label": "How we''ll check in on whether it''s helping"}]'::jsonb, array['addiction', 'relationships', 'relapse prevention']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('anger-recovery-time-log', 'Anger Recovery Time Log', 'worksheet'::resource_kind, 'A log of how long the body takes to settle after anger spikes, tracked across the week.', 'Use it to spot whether recovery time after anger episodes is shrinking or stuck.', array['Adults', 'Teens']::text[], 'One week, a few minutes per entry', 'Most anger work focuses on triggers and warning signs, but how long the body stays activated afterward matters too. Have the client log the time from an anger spike to feeling settled again, along with what helped the comedown. Patterns often show certain settings or people stretch recovery out, and some go-to strategies shorten it fast. Bring the week''s entries into session and look for the outliers together, rather than just averaging the numbers.', '[{"id": "f0", "type": "textarea", "label": "What set off my anger today"}, {"id": "f1", "type": "textarea", "label": "Time I noticed the spike"}, {"id": "f2", "type": "textarea", "label": "Time I felt back to my normal self"}, {"id": "f3", "type": "textarea", "label": "What helped me settle faster"}, {"id": "f4", "type": "textarea", "label": "What made it take longer"}]'::jsonb, array['anger management', 'anger', 'self-monitoring']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('hostile-attribution-recheck', 'Hostile Attribution Recheck', 'cbt'::resource_kind, 'A CBT worksheet that tests a hostile first read of someone''s behavior against kinder alternatives.', 'Use it to slow the jump from an ambiguous situation straight to feeling disrespected.', array['Adults', 'Teens']::text[], '15 minutes', 'Anger often follows a snap judgment that someone meant to be inconsiderate or disrespectful, before any other explanation gets considered. Walk the client through a recent moment that sparked anger: the first, hostile read of what happened, then two or three other explanations that fit the same facts just as well. Rate how angry each version feels on its own. The goal isn''t to talk the client out of their anger, but to show how much of the heat comes from the interpretation chosen, not the event itself.', '[{"id": "f0", "type": "textarea", "label": "The situation that made me angry"}, {"id": "f1", "type": "textarea", "label": "My first read on what happened"}, {"id": "f2", "type": "textarea", "label": "A second explanation that also fits the facts"}, {"id": "f3", "type": "textarea", "label": "A third explanation that also fits the facts"}, {"id": "f4", "type": "textarea", "label": "How angry each version makes me feel, 0 to 10"}]'::jsonb, array['anger management', 'cognitive flexibility', 'automatic thoughts']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('being-right-vs-being-effective-check', 'Being Right vs Being Effective Check', 'dbt'::resource_kind, 'A DBT-informed check-in that weighs winning the argument against getting what actually matters.', 'Use it to help a client choose effectiveness over being right in a heated moment.', array['Adults', 'Teens']::text[], 'Five minutes in the moment', 'Borrowed from the DBT idea of choosing effectiveness over being right, this card gives a client three quick questions to run through mid-conflict: what do I actually want here, does proving my point get me closer to it, and what would the wise-mind version of me do instead. It works best rehearsed calm first, then carried as a card or phone note for the real moment. Some clients resist it at first because being right feels like the whole point; naming that resistance out loud in session usually helps.', '[{"id": "f0", "type": "textarea", "label": "What I actually want from this situation"}, {"id": "f1", "type": "textarea", "label": "Does proving my point get me closer to that?"}, {"id": "f2", "type": "textarea", "label": "What would my wise mind do here?"}, {"id": "f3", "type": "textarea", "label": "What I''ll say or do instead of pushing to win"}]'::jsonb, array['anger management', 'core DBT', 'interpersonal effectiveness']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('anger-thermostat-dial', 'Anger Thermostat Dial', 'kids'::resource_kind, 'A paper dial a child builds and colors to show how hot their anger is getting right now.', 'Use it to give a child a hands-on way to notice and turn down rising anger.', array['Children']::text[], '20 minutes to build, then ongoing', 'The child cuts out a simple dial and colors zones from cool blue through hot red, then writes or draws one calming move next to each zone, like squeezing a pillow or asking for space. Tape a spare paper arrow on with a brass fastener so it turns. The caregiver''s job is to notice out loud when the dial creeps toward red and invite the child to move the arrow themselves rather than announcing how they feel. Keep the finished dial somewhere visible, like a bedroom door, so it becomes a shared cue.', '[{"id": "f0", "type": "textarea", "label": "Colors for each zone of my dial, cool to hot"}, {"id": "f1", "type": "textarea", "label": "One thing that helps me at the blue zone"}, {"id": "f2", "type": "textarea", "label": "One thing that helps me at the yellow zone"}, {"id": "f3", "type": "textarea", "label": "One thing that helps me at the red zone"}, {"id": "f4", "type": "textarea", "label": "Where we''ll keep the dial at home"}]'::jsonb, array['anger management', 'children', 'self-soothing']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('escalation-signal-system', 'Escalation Signal System', 'couples'::resource_kind, 'A private signal couples agree on ahead of time to flag rising anger before it boils over.', 'Use it to help partners interrupt escalation earlier than a full blowup.', array['Couples']::text[], '20 minutes to set up, then ongoing', 'Have each partner name their own early signs of rising anger, then agree together on one word or gesture either of them can use the moment those signs show up, no explanation required in the heat of the moment. The signal''s only job is to pause the conversation, not to win it or assign blame. Some couples pick a word, others a hand on the table. Practice using it once in session on a low-stakes disagreement so it doesn''t feel awkward the first time it''s needed for real.', '[{"id": "f0", "type": "textarea", "label": "Partner A''s early signs of rising anger"}, {"id": "f1", "type": "textarea", "label": "Partner B''s early signs of rising anger"}, {"id": "f2", "type": "textarea", "label": "Our agreed signal word or gesture"}, {"id": "f3", "type": "textarea", "label": "What happens after the signal is given"}, {"id": "f4", "type": "textarea", "label": "How the practice round in session went"}]'::jsonb, array['anger management', 'de-escalation', 'communication']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('mental-ritual-tally-sheet', 'Mental Ritual Tally Sheet', 'worksheet'::resource_kind, 'A simple tally for mental rituals like counting, praying, or replaying a moment, not just visible ones.', 'Use it to bring silent, mental compulsions into view alongside physical ones.', array['Adults', 'Teens']::text[], 'One week', 'Mental rituals are easy to miss because there''s nothing to see, so clients often undercount them next to hand-washing or checking. Ask the client to carry a small tally sheet and mark a line each time they notice themselves counting, praying, reviewing, or mentally fixing a thought on purpose, without stopping to analyze it in the moment. The running total across a week often surprises people, and the sheet becomes a starting point for choosing one mental ritual to work on directly in session.', '[{"id": "f0", "type": "textarea", "label": "Type of mental ritual I noticed (counting, praying, reviewing, other)"}, {"id": "f1", "type": "textarea", "label": "Tally marks for today"}, {"id": "f2", "type": "textarea", "label": "What was happening right before it started"}, {"id": "f3", "type": "textarea", "label": "One mental ritual I want to work on next"}]'::jsonb, array['OCD', 'self-monitoring', 'triggers']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('thought-action-fusion-checker', 'Thought-Action Fusion Checker', 'cbt'::resource_kind, 'A worksheet that tests the belief that having a thought is as risky as acting on it.', 'Use it to separate the content of an intrusive thought from its imagined power.', array['Adults', 'Teens']::text[], '20 minutes', 'Many people with intrusive thoughts believe, often without naming it, that thinking something makes it more likely to happen or is morally equal to doing it. Have the client write down a recent intrusive thought, then rate two separate beliefs: how likely the thought is to come true just because they had it, and how much having it says about their character. Compare those ratings to a thought they''d call neutral, like thinking about the weather. Most clients notice the two thoughts aren''t held to the same logical standard, which is worth sitting with.', '[{"id": "f0", "type": "textarea", "label": "The intrusive thought"}, {"id": "f1", "type": "textarea", "label": "How likely I think it is to come true just from thinking it, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "How much I think it says about my character, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "A neutral thought for comparison"}, {"id": "f4", "type": "textarea", "label": "Same two ratings for the neutral thought"}]'::jsonb, array['OCD', 'cognitive flexibility', 'automatic thoughts']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('naming-the-ocd-voice', 'Naming the OCD Voice', 'act'::resource_kind, 'An ACT defusion exercise that labels intrusive OCD demands as a voice, not a command.', 'Use it to help a client notice OCD''s urgency without automatically obeying it.', array['Adults', 'Teens']::text[], '15 minutes, then ongoing practice', 'Give the urgency behind an obsession a name, like ''the OCD voice'' or a nickname the client picks themselves, so it''s easier to notice as one voice among many rather than the whole truth. When an obsession fires, the client silently says ''there''s the voice again'' instead of arguing with the content or rushing to comply with a ritual. This isn''t about proving the voice wrong, which usually fuels more looping; it''s about creating a small gap between hearing the demand and acting on it.', '[{"id": "f0", "type": "textarea", "label": "The nickname I''m giving the OCD voice"}, {"id": "f1", "type": "textarea", "label": "What the voice said today"}, {"id": "f2", "type": "textarea", "label": "What I did after noticing it was ''the voice'' talking"}, {"id": "f3", "type": "textarea", "label": "How much space I felt between hearing it and reacting"}]'::jsonb, array['OCD', 'defusion', 'self-as-context']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('just-right-feeling-practice', 'Just-Right Feeling Practice', 'kids'::resource_kind, 'A sticker practice where a child leaves something a little imperfect on purpose and rides out the feeling.', 'Use it to help a child practice tolerating a not-quite-right feeling without fixing it.', array['Children']::text[], 'Five minutes, a few times a week', 'Some children get stuck needing things lined up, matched, or repeated until they feel just right, and fixing the urge in the moment only strengthens it. Pick one small, safe thing to leave imperfect on purpose, like an uneven stack of blocks or a crooked sticker, and set a timer for how long to leave it alone. The child earns a sticker for the practice itself, not for how it feels afterward. The caregiver''s job is to stay calm and not fix it either, even if asked, and to point out that the feeling faded on its own.', '[{"id": "f0", "type": "textarea", "label": "What we left a little imperfect today"}, {"id": "f1", "type": "textarea", "label": "How long we set the timer for"}, {"id": "f2", "type": "textarea", "label": "How big the not-quite-right feeling was, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "How big it was by the end of the timer"}]'::jsonb, array['OCD', 'children', 'uncertainty']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('uncertainty-dice-challenge', 'Uncertainty Dice Challenge', 'game'::resource_kind, 'A dice game where each roll hands the client a small, safe uncertainty challenge to sit with.', 'Use it to practice tolerating uncertainty in a lower-stakes, playful format.', array['Adults', 'Teens']::text[], '20 minutes', 'Before rolling, build a list of six small uncertainty challenges together, ranked roughly easy to harder, like sending a text without rereading it or leaving a room without checking the stove twice. Each number on the die maps to one challenge. The client rolls, completes that challenge before the next session if possible, and rates how tolerable the not-knowing felt afterward, not right away. Roll again for a harder set once the easier challenges stop feeling like a big deal. Close each round with one debrief question.', '[{"id": "f0", "type": "textarea", "label": "Our six challenges, numbered 1 to 6"}, {"id": "f1", "type": "textarea", "label": "Number rolled"}, {"id": "f2", "type": "textarea", "label": "How tolerable the not-knowing felt afterward, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Debrief: what did not-knowing actually cost me this time?"}]'::jsonb, array['OCD', 'uncertainty', 'exposure']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('panic-aftermath-reset', 'Panic Aftermath Reset', 'worksheet'::resource_kind, 'A short checklist for right after a panic attack passes, before the memory of it gets set.', 'Use it to help a client reset and reorient in the minutes just after an attack fades.', array['Adults', 'Teens']::text[], 'Five minutes, right after an episode', 'Most panic tools focus on the buildup or the middle of an attack, leaving the immediate aftermath unaddressed, which is often when a frightening memory of the episode gets cemented. Right after the peak fades, have the client name three things they can see, take a sip of water, and jot one line about what actually happened versus what they feared would happen. This isn''t about analyzing the attack in depth; it''s a short reset before returning to whatever they were doing. Bring the collected sheets into session to look for patterns across episodes.', '[{"id": "f0", "type": "textarea", "label": "Three things I can see right now"}, {"id": "f1", "type": "textarea", "label": "What I feared would happen"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "One word for how I feel right now"}]'::jsonb, array['panic attacks', 'self-monitoring', 'grounding']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('panic-safety-behavior-drop-out', 'Panic Safety Behavior Drop-Out', 'cbt'::resource_kind, 'A behavioral experiment that drops one safety behavior at a time to test what actually happens.', 'Use it to test whether a safety behavior is preventing harm or just preventing discomfort.', array['Adults', 'Teens']::text[], 'One safety behavior per week', 'Clients with panic often carry a safety behavior, like gripping a water bottle, sitting near an exit, or checking their pulse, believing it''s the only thing keeping a feared outcome from happening. Pick one low-stakes safety behavior and agree on a single outing where the client drops it on purpose, predicting beforehand what they think will happen without it. Afterward, compare the prediction to what actually happened. The point isn''t to prove panic won''t happen; it''s to test whether the behavior was really necessary.', '[{"id": "f0", "type": "textarea", "label": "The safety behavior I''m dropping"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen without it"}, {"id": "f2", "type": "textarea", "label": "How confident I am in that prediction, 0 to 100%"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What this tells me about the safety behavior"}]'::jsonb, array['panic attacks', 'behavioral experiment', 'safety behaviors']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('panic-escape-urge-surf', 'Panic Escape Urge Surf', 'dbt'::resource_kind, 'A DBT-style log that tracks the urge to flee a panic attack instead of acting on it right away.', 'Use it to help a client ride out the urge to escape until it crests and falls.', array['Adults', 'Teens']::text[], 'During an episode, then reviewed weekly', 'Borrowing the DBT idea of surfing an urge instead of immediately obeying it, this log has the client rate the urge to leave or escape a situation every couple of minutes during a panic episode, rather than acting on the first spike. Most urges to flee crest within several minutes even when the panic itself takes longer to fully settle. Reviewing the ratings afterward in session shows the client, in their own numbers, that the urge has a shape and an end, which is easy to forget in the moment.', '[{"id": "f0", "type": "textarea", "label": "Where I was when the urge to escape started"}, {"id": "f1", "type": "textarea", "label": "Urge to leave, rated every few minutes"}, {"id": "f2", "type": "textarea", "label": "What I did instead of leaving"}, {"id": "f3", "type": "textarea", "label": "How long until the urge dropped"}]'::jsonb, array['panic attacks', 'core DBT', 'urges']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('partner-reassurance-boundaries-conversation', 'Partner Reassurance Boundaries Conversation', 'couples'::resource_kind, 'A structured talk about how much reassurance around panic actually helps versus keeps it going.', 'Use it to help partners agree on a reassurance plan instead of improvising in the moment.', array['Couples']::text[], '30 minutes', 'Partners of someone with panic often end up over-reassuring without meaning to, answering the same what-if question many times a day because refusing feels unkind in the moment, even though it tends to keep the worry cycle going. Have each partner name what reassurance currently looks like between them, then agree together on a smaller, specific version, like answering a health worry once and then redirecting to a plan instead of re-litigating it. Revisit the agreement after a couple of weeks since it usually needs adjusting.', '[{"id": "f0", "type": "textarea", "label": "What reassurance currently looks like between us"}, {"id": "f1", "type": "textarea", "label": "Partner A''s part of the new agreement"}, {"id": "f2", "type": "textarea", "label": "Partner B''s part of the new agreement"}, {"id": "f3", "type": "textarea", "label": "How it went when we tried it this week"}]'::jsonb, array['panic attacks', 'accommodation', 'communication']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('panic-alarm-off-switch-craft', 'Panic Alarm Off-Switch Craft', 'kids'::resource_kind, 'A craft where a child builds a pretend alarm switch and labels it with their own calm-down move.', 'Use it to give a child a hands-on way to understand panic as a false alarm they can turn off.', array['Children', 'Teens']::text[], '20 minutes to build, then ongoing', 'Explain panic to a child as the body''s alarm system going off by mistake, like a smoke detector triggered by toast instead of a real fire. The child decorates a paper switch or button, writes one or two body clues next to it that mean the alarm is going off, like a racing heart or shaky hands, and one action next to the switch that helps turn the volume down, like slow breathing or squeezing a stress ball. Keep the craft somewhere the child can point to it. The caregiver''s role is to name the false alarm calmly rather than reacting with worry.', '[{"id": "f0", "type": "textarea", "label": "Body clues that mean my alarm is going off"}, {"id": "f1", "type": "textarea", "label": "My off-switch action"}, {"id": "f2", "type": "textarea", "label": "Where we''ll keep my alarm switch craft"}, {"id": "f3", "type": "textarea", "label": "How it went the last time we used it"}]'::jsonb, array['panic attacks', 'children', 'body awareness']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('sibling-conflict-pattern-log', 'Sibling Conflict Pattern Log', 'worksheet'::resource_kind, 'A log that tracks who, what, and when in sibling conflicts instead of relitigating each one live.', 'Use it to spot the recurring pattern underneath repeated sibling fights.', array['Adults']::text[], 'One to two weeks', 'Sibling conflict often gets handled fight by fight, with parents trying to reconstruct who started it in the moment, which rarely goes anywhere useful. Have the parent jot a quick line after each conflict this week: who was involved, roughly what triggered it, time of day, and how it ended, without trying to assign blame on the spot. Bring the log into session and look across entries for the pattern, like a particular time of day, activity, or tired sibling that shows up again and again.', '[{"id": "f0", "type": "textarea", "label": "Who was involved"}, {"id": "f1", "type": "textarea", "label": "What seemed to trigger it"}, {"id": "f2", "type": "textarea", "label": "Time of day"}, {"id": "f3", "type": "textarea", "label": "How it ended"}, {"id": "f4", "type": "textarea", "label": "Pattern I''m starting to notice across entries"}]'::jsonb, array['parenting', 'family', 'pattern']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('child-behavior-reframe-card', 'Child Behavior Reframe Card', 'cbt'::resource_kind, 'A CBT card that tests a parent''s harshest read of a child''s behavior against kinder alternatives.', 'Use it to slow a parent''s jump from a child''s behavior to a story about their character.', array['Adults']::text[], '10 minutes', 'Parents under stress often land on the harshest available explanation for a child''s behavior, like ''he''s doing this on purpose to get at me,'' and respond to that story rather than to what actually happened. Have the parent write down a recent moment that frustrated them, their first read on why the child did it, and two other explanations that fit the same facts, like tiredness, a skill the child hasn''t learned yet, or a need the child can''t name. Rate how frustrated each version feels.', '[{"id": "f0", "type": "textarea", "label": "The behavior that frustrated me"}, {"id": "f1", "type": "textarea", "label": "My first read on why my child did it"}, {"id": "f2", "type": "textarea", "label": "A second explanation that also fits"}, {"id": "f3", "type": "textarea", "label": "A third explanation that also fits"}, {"id": "f4", "type": "textarea", "label": "How frustrated each version makes me feel, 0 to 10"}]'::jsonb, array['parenting', 'cognitive flexibility', 'automatic thoughts']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('family-helper-chart-craft', 'Family Helper Chart Craft', 'kids'::resource_kind, 'A chart a child helps design to track family jobs, not just one child''s individual rewards.', 'Use it to give a child ownership over contributing to the family, not just earning points.', array['Children']::text[], '20 minutes to build, then ongoing', 'Unlike a chart built around one child''s target behavior, this one is about the whole family pitching in. The child helps pick and draw icons for a handful of real household jobs, some theirs and some a parent''s or sibling''s, and the family moves a marker to whoever did which job that day. There''s no prize for finishing; the point is visibility of who''s contributing. Parents should resist turning it into a scorecard for arguments and instead use it as a quick, low-drama way to notice when the load has quietly shifted onto one person.', '[{"id": "f0", "type": "textarea", "label": "Jobs we picked and who usually does each one"}, {"id": "f1", "type": "textarea", "label": "Who did what today"}, {"id": "f2", "type": "textarea", "label": "Anything that felt unfair this week"}, {"id": "f3", "type": "textarea", "label": "One job we want to swap or share differently"}]'::jsonb, array['parenting', 'children', 'routines']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('united-front-discipline-script', 'United Front Discipline Script', 'couples'::resource_kind, 'A pre-written script two parents agree on ahead of time for common discipline moments.', 'Use it to help co-parents respond the same way instead of contradicting each other live.', array['Couples']::text[], '30 minutes', 'Kids often get mixed signals when parents improvise discipline separately in the moment, and disagreeing in front of a child tends to escalate things further. Pick three or four scenarios that come up often, like bedtime refusal or a meltdown in public, and have each partner write what they''d currently say or do. Work out one shared response for each scenario together, agreeing that whichever parent is present uses the shared line, and any disagreement about it happens later, privately. Revisit the script after a few weeks.', '[{"id": "f0", "type": "textarea", "label": "Scenario"}, {"id": "f1", "type": "textarea", "label": "What Partner A currently says or does"}, {"id": "f2", "type": "textarea", "label": "What Partner B currently says or does"}, {"id": "f3", "type": "textarea", "label": "Our shared response for this scenario"}, {"id": "f4", "type": "textarea", "label": "How it held up in real life this week"}]'::jsonb, array['parenting', 'communication', 'family']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('family-meeting-turn-token-game', 'Family Meeting Turn Token Game', 'game'::resource_kind, 'A token-based turn-taking game that keeps family meetings from being run by the loudest voice.', 'Use it to give every family member an equal, visible turn to speak at a family meeting.', array['Groups', 'Children']::text[], '20 to 30 minutes', 'Give each family member the same number of tokens, three or four, at the start of the meeting. Spending a token is the only way to speak on the agenda; once tokens run out, that person listens until the next round. A parent keeps time and calls rounds, but doesn''t get extra tokens. This levels out meetings that usually run on whoever talks fastest or loudest, and often surprises families with how much a quieter kid has to say once given guaranteed turns. Close every meeting with one debrief question.', '[{"id": "f0", "type": "textarea", "label": "Number of tokens each person gets"}, {"id": "f1", "type": "textarea", "label": "What I used a token to say"}, {"id": "f2", "type": "textarea", "label": "One thing we decided together"}, {"id": "f3", "type": "textarea", "label": "Debrief: what''s one thing we''re doing differently because of today?"}]'::jsonb, array['parenting', 'family', 'communication']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('postpartum-return-to-work-transition-map', 'Postpartum Return-to-Work Transition Map', 'worksheet'::resource_kind, 'Maps the logistics and feelings tangled up in a parent''s return to paid work.', 'Use it to separate practical return-to-work logistics from the guilt underneath.', array['Adults']::text[], '20 minutes', 'Have the client list what returning to work actually requires — childcare, pumping or feeding logistics, schedule negotiations — on one side, and the feelings that surface when they picture it on the other. Many clients arrive treating the whole transition as one undifferentiated dread; splitting the practical from the emotional usually reveals that one or two concrete items are driving most of the distress and can be planned for directly, while the rest is feeling that needs space rather than a fix.', '[{"id": "f0", "type": "textarea", "label": "What returning to work will actually require, day to day"}, {"id": "f1", "type": "textarea", "label": "The feelings that come up when I picture my first day back"}, {"id": "f2", "type": "textarea", "label": "Which of these feelings are about logistics I can plan for"}, {"id": "f3", "type": "textarea", "label": "Which are about something else entirely"}, {"id": "f4", "type": "textarea", "label": "One logistical piece I can start arranging this week"}]'::jsonb, array['perinatal and postpartum', 'transitions', 'planning']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('bonding-expectations-reality-check', 'Bonding Expectations Reality Check', 'cbt'::resource_kind, 'Tests a new parent''s predictions about instant bonding against what actually unfolds.', 'Use it to loosen the belief that bonding must feel a certain way right away.', array['Adults']::text[], 'One week', 'Before an upcoming stretch of caregiving time, the client writes down what they predict they will feel and how strongly they expect to feel it. Afterward they record what actually happened. Most new parents carry an unspoken rule that bonding should arrive instantly and constantly; running this a few times usually shows feelings arriving in patches, delayed, or mixed with exhaustion, which is ordinary rather than a sign anything is wrong. Watch for clients who mark every non-instant moment as a failure.', '[{"id": "f0", "type": "textarea", "label": "My prediction: what I expect to feel during this stretch of caregiving"}, {"id": "f1", "type": "textarea", "label": "How strongly I expect to feel it (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "How strongly I actually felt it (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "What this tells me about my rule for how bonding is supposed to feel"}]'::jsonb, array['perinatal and postpartum', 'behavioral experiment', 'evidence']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('postpartum-guilt-defusion-practice', 'Postpartum Guilt Defusion Practice', 'act'::resource_kind, 'A short defusion practice for the guilt thoughts that follow ordinary parenting moments.', 'Use it to help a new parent hold guilt thoughts more lightly instead of obeying them.', array['Adults']::text[], 'Five minutes daily for two weeks', 'When a guilt thought shows up — about formula, screen time, snapping at a partner, wanting a break — the client says it in full as ''I''m noticing the thought that I am a bad parent because...'' rather than as flat fact, then names one value the moment still served, like patience or honesty. The point is not to argue the thought away but to loosen its grip enough that it stops driving the next decision. New parents often want reassurance the thought is false; redirect toward noticing rather than debating it.', '[{"id": "f0", "type": "textarea", "label": "A guilt thought I had this week"}, {"id": "f1", "type": "textarea", "label": "The same thought said as ''I''m noticing the thought that...''"}, {"id": "f2", "type": "textarea", "label": "A value this moment still served, even with the guilt attached"}, {"id": "f3", "type": "textarea", "label": "What I did next, guilt thought and all"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'self-blame']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('newborn-load-fairness-conversation', 'Newborn Load Fairness Conversation', 'couples'::resource_kind, 'A structured talk for partners to name who is carrying the invisible newborn workload.', 'Use it to surface resentment about uneven newborn labor before it hardens into conflict.', array['Couples']::text[], '30 minutes', 'Each partner separately lists the tasks, visible and invisible, that filled their week with the baby — feeding, laundry, remembering appointments, worrying overnight — then partners trade lists and each names one item on the other''s list they had not noticed. Couples often discover the imbalance is less about hours than about who is holding the mental load of remembering and anticipating. Keep the exchange to naming and noticing in session; save any renegotiation of duties for a separate conversation.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks that filled my week with the baby"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks that filled my week with the baby"}, {"id": "f2", "type": "textarea", "label": "Partner A: one thing on Partner B''s list I hadn''t noticed"}, {"id": "f3", "type": "textarea", "label": "Partner B: one thing on Partner A''s list I hadn''t noticed"}, {"id": "f4", "type": "textarea", "label": "One piece of invisible work we want to name out loud going forward"}]'::jsonb, array['perinatal and postpartum', 'fairness', 'conflict']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('postpartum-anger-opposite-action-plan', 'Postpartum Anger Opposite Action Plan', 'dbt'::resource_kind, 'Applies opposite action to the sharp irritability many new parents feel but rarely name.', 'Use it to give a new parent a concrete alternative to snapping when irritability spikes.', array['Adults']::text[], 'Ongoing, reviewed weekly', 'Have the client identify the situations that reliably spike irritability in the newborn stretch — being touched out, interrupted sleep, unsolicited advice — and rate whether the anger fits the situation or is amplified by exhaustion. For anger that is amplified rather than fitting, they plan one opposite action in advance: softening posture, stepping into another room for sixty seconds, or asking for a handoff instead of pushing through. This works best rehearsed in session before the next hard moment, not invented in the moment itself.', '[{"id": "f0", "type": "textarea", "label": "A moment this week when irritability spiked"}, {"id": "f1", "type": "textarea", "label": "Does the anger fit the situation, or is exhaustion amplifying it"}, {"id": "f2", "type": "textarea", "label": "My planned opposite action for next time"}, {"id": "f3", "type": "textarea", "label": "What happened when I tried it"}]'::jsonb, array['perinatal and postpartum', 'opposite action', 'anger']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('self-worth-sources-pie-chart', 'Self-Worth Sources Pie Chart', 'worksheet'::resource_kind, 'Maps how much of a client''s sense of worth currently rests on each area of life.', 'Use it to show a client when self-worth is riding almost entirely on one shaky category.', array['Adults', 'Teens']::text[], '20 minutes', 'The client divides a circle into slices representing where their sense of worth currently comes from — work performance, a relationship, parenting, appearance, being liked — sized by how much weight each one carries, then draws a second circle showing how they would like the slices to look. Clients are often startled to see one slice, usually achievement or others'' approval, taking up most of the pie; that concentration is what makes a single setback feel like a referendum on their whole worth.', '[{"id": "f0", "type": "textarea", "label": "Current pie: where my sense of worth comes from right now"}, {"id": "f1", "type": "textarea", "label": "What happens to me when the biggest slice takes a hit"}, {"id": "f2", "type": "textarea", "label": "Wished-for pie: how I''d like the slices sized instead"}, {"id": "f3", "type": "textarea", "label": "One small step toward growing a smaller slice"}]'::jsonb, array['self-esteem', 'core beliefs']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('double-standard-self-talk-worksheet', 'Double Standard Self-Talk Worksheet', 'cbt'::resource_kind, 'Compares what a client tells themselves to what they would tell a friend in the same spot.', 'Use it to expose the harsher rulebook a client applies only to themselves.', array['Adults', 'Teens']::text[], '15 minutes', 'The client writes down exactly what they said to themselves after a recent mistake or setback, then imagines a close friend in the identical situation and writes what they would actually say to that friend. Reading the two side by side usually makes the double standard obvious without the clinician needing to point it out. Some clients insist the harsher version is simply accurate; if so, ask what evidence would change their mind, and note the answer for later sessions.', '[{"id": "f0", "type": "textarea", "label": "What I said to myself after it happened"}, {"id": "f1", "type": "textarea", "label": "The situation, in one line, as I''d describe it to a friend"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend in that exact situation"}, {"id": "f3", "type": "textarea", "label": "What''s different between the two, in my own words"}]'::jsonb, array['self-esteem', 'core beliefs', 'self-criticism']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('self-worth-weather-practice', 'Self-Worth Weather Practice', 'act'::resource_kind, 'A defusion metaphor that treats self-worth judgments as passing weather, not fixed fact.', 'Use it to help a client notice harsh self-judgments without treating them as permanent.', array['Adults', 'Teens']::text[], 'Ten minutes daily for two weeks', 'Ask the client to name today''s self-worth weather in a sentence or two — a storm of not-good-enough, a fog of comparison, a clear stretch — without trying to fix or argue with it, simply logging what passed through. Over a couple of weeks the log usually shows the weather changing on its own, which loosens the assumption that a bad-weather day means something is permanently true about them. Clients who want to debate whether the weather is accurate can be redirected toward simply describing it.', '[{"id": "f0", "type": "textarea", "label": "Today''s self-worth weather, in a sentence"}, {"id": "f1", "type": "textarea", "label": "What was happening around it, if anything"}, {"id": "f2", "type": "textarea", "label": "Did I try to fix it, argue with it, or just let it pass"}, {"id": "f3", "type": "textarea", "label": "What the weather looked like a day or two later"}]'::jsonb, array['self-esteem', 'defusion', 'self-as-context']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('confidence-wager-game', 'Confidence Wager Game', 'game'::resource_kind, 'A turn-based game where a client bets on their own confidence before trying something small.', 'Use it to close the gap between predicted and actual confidence through small tries.', array['Adults', 'Teens']::text[], '20 minutes', 'Before each small in-session challenge — asking a direct question, holding eye contact for a count, stating an opinion out loud — the client wagers a number of chips on how confident they feel it will go well, from a shared pile of ten. After each attempt, the clinician and client compare the wager to how it actually went and the client either collects or forfeits chips based on how close the prediction was. Play three to five rounds and debrief with one question: what moved the wager most, the task or the guess?', '[{"id": "f0", "type": "textarea", "label": "The small challenge I''m about to try"}, {"id": "f1", "type": "textarea", "label": "My confidence wager before trying (chips out of 10)"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "Was my wager close, too low, or too high"}]'::jsonb, array['self-esteem', 'exposure']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('mirror-of-me-self-portrait-craft', 'Mirror of Me Self-Portrait Craft', 'kids'::resource_kind, 'A decorated self-portrait frame where a child writes good things about who they are.', 'Use it to give a child a keepsake that reflects back their own strengths in their words.', array['Children']::text[], '30 minutes', 'The child draws a self-portrait in the middle of a page, then decorates a mirror-shaped frame around it, writing or dictating one good thing about themselves in each ray or petal of the frame — kind, funny, good at building things. The parent''s job is to add one thing they notice too, in a different color, without correcting or upgrading what the child already wrote. Some children fill the frame quickly and others need prompts; a short list of starter words on a side card helps without putting words in their mouth.', '[{"id": "f0", "type": "textarea", "label": "My self-portrait"}, {"id": "f1", "type": "textarea", "label": "Good things about me (one per ray of the frame)"}, {"id": "f2", "type": "textarea", "label": "What my grown-up noticed about me too"}, {"id": "f3", "type": "textarea", "label": "Where I want to hang this"}]'::jsonb, array['self-esteem', 'children', 'art']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('safety-behavior-fade-out-plan', 'Safety Behavior Fade-Out Plan', 'worksheet'::resource_kind, 'A stepped plan for dropping the small protective habits that keep social fear alive.', 'Use it to phase out safety behaviors gradually instead of all at once.', array['Adults', 'Teens']::text[], 'Several weeks', 'List the small habits the client uses to get through social situations — rehearsing lines in advance, avoiding eye contact, gripping a drink, staying near the exit — then rank them from easiest to hardest to drop. Rather than removing all of them at once, the client picks one to fade out in a specific upcoming situation and predicts what they fear will happen without it. Fading behaviors one at a time keeps the task manageable and makes it easier to trace which one was actually holding the fear in place.', '[{"id": "f0", "type": "textarea", "label": "My safety behaviors, ranked easiest to hardest to drop"}, {"id": "f1", "type": "textarea", "label": "The one I''m dropping this week, and in which situation"}, {"id": "f2", "type": "textarea", "label": "What I predict will happen without it"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}]'::jsonb, array['social anxiety', 'safety behaviors', 'exposure']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('video-feedback-comparison-worksheet', 'Video Feedback Comparison Worksheet', 'cbt'::resource_kind, 'Compares a client''s imagined social self-image to a brief recording of how they came across.', 'Use it to correct the distorted self-image many clients rely on in social situations.', array['Adults', 'Teens']::text[], 'One session', 'Before a short recorded role-play or conversation, the client describes in detail how they expect to look and sound — flushed, stumbling, obviously nervous. After watching the recording back once, with the clinician present, they note what they actually saw compared to the prediction. Most clients are watching for their own internal experience rather than an external audience, and this usually narrows the gap between the two considerably. Keep the clip short and review it together rather than leaving it as homework.', '[{"id": "f0", "type": "textarea", "label": "How I expect to look and sound before watching"}, {"id": "f1", "type": "textarea", "label": "What I actually noticed watching the recording"}, {"id": "f2", "type": "textarea", "label": "The biggest difference between the two"}, {"id": "f3", "type": "textarea", "label": "What this changes about what I focus on next time"}]'::jsonb, array['social anxiety', 'core CBT', 'self-doubt']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('wise-mind-check-before-social-events', 'Wise Mind Check Before Social Events', 'dbt'::resource_kind, 'A short pre-event check-in that weighs fear against facts before deciding whether to go.', 'Use it to help a client decide from wise mind instead of avoidance in the moment.', array['Adults', 'Teens']::text[], 'Ten minutes before an event', 'Shortly before a social event the client is dreading, have them write the emotion-mind story first — the worst-case version fear is telling them — then the reasonable-mind facts on their own, separate from the story. Wise mind is the short, honest sentence that sits between the two once both are on paper. This is meant to happen in the minutes before the event, not as a homework reflection afterward, so the clinician may need to walk through it once together before the client tries it alone.', '[{"id": "f0", "type": "textarea", "label": "Emotion mind: the story fear is telling me right now"}, {"id": "f1", "type": "textarea", "label": "Reasonable mind: the plain facts, without the story"}, {"id": "f2", "type": "textarea", "label": "Wise mind: one honest sentence that holds both"}, {"id": "f3", "type": "textarea", "label": "My decision"}]'::jsonb, array['social anxiety', 'wise mind', 'core DBT']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('brave-cape-for-meeting-new-people-craft', 'Brave Cape for Meeting New People Craft', 'kids'::resource_kind, 'A wearable cape a child decorates with reminders for meeting new people or groups.', 'Use it to give a child a physical, wearable cue for courage in new social moments.', array['Children']::text[], '30 minutes', 'Cut a simple cape shape from fabric or paper and let the child decorate it with colors, stickers, or drawings that make them feel brave, then help them write or dictate one small brave step for meeting new people on each side — a wave, a hello, asking a name. The parent''s role is to help the child put the cape on before a real situation that calls for it, like a birthday party or a new class, and to name the brave step out loud rather than pushing the child to use all of them at once.', '[{"id": "f0", "type": "textarea", "label": "My cape design"}, {"id": "f1", "type": "textarea", "label": "Brave steps written on my cape"}, {"id": "f2", "type": "textarea", "label": "Where I wore my cape"}, {"id": "f3", "type": "textarea", "label": "Which brave step I tried"}]'::jsonb, array['social anxiety', 'children', 'art']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('small-talk-question-bingo', 'Small Talk Question Bingo', 'game'::resource_kind, 'A bingo card of low-stakes small talk questions to practice asking and answering in session.', 'Use it to build small talk fluency through low-stakes repeated practice.', array['Teens', 'Adults', 'Groups']::text[], '20 minutes', 'Fill a bingo grid with easy small talk questions — favorite way to spend a weekend, a show they''re watching, where they grew up — and take turns asking each other questions from the grid, marking a square once it''s been asked and answered by both people. In a group, mix up pairs after each bingo line. Debrief with one question afterward: which square felt easiest to ask, and which one did you almost skip? The skill being practiced is initiating, not the content of the answers.', '[{"id": "f0", "type": "textarea", "label": "Squares I marked off"}, {"id": "f1", "type": "textarea", "label": "The easiest question to ask"}, {"id": "f2", "type": "textarea", "label": "The one I almost skipped"}, {"id": "f3", "type": "textarea", "label": "What I noticed in my body while asking"}]'::jsonb, array['social anxiety', 'social skills', 'exposure']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('anniversary-and-milestone-planning-sheet', 'Anniversary and Milestone Planning Sheet', 'worksheet'::resource_kind, 'Plans support and coping ahead of known hard dates like anniversaries and holidays.', 'Use it to prepare for a specific hard date instead of being caught off guard by it.', array['Adults', 'Teens']::text[], '20 minutes', 'Have the client name an upcoming date they expect to be hard — a death anniversary, a birthday, a holiday the person is missing from — and plan it out in advance: who they want nearby, what they want to do or avoid, and one way to mark the day on their own terms. Clients often discover the anticipation in the days before is harder than the date itself; having a plan on paper, even a loose one, tends to shrink that lead-up dread considerably. Revisit the plan the session before the date if timing allows.', '[{"id": "f0", "type": "textarea", "label": "The upcoming date and why it matters"}, {"id": "f1", "type": "textarea", "label": "Who I want with me, or if I want to be alone"}, {"id": "f2", "type": "textarea", "label": "What I want to do to mark the day"}, {"id": "f3", "type": "textarea", "label": "What I want to avoid that day"}, {"id": "f4", "type": "textarea", "label": "One thing that helped last time a hard date came around"}]'::jsonb, array['grief and loss', 'planning', 'bereavement']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('if-only-thoughts-sorting-grid', 'If-Only Thoughts Sorting Grid', 'cbt'::resource_kind, 'Sorts the ''if only I had'' thoughts after a loss into what was and wasn''t in the client''s control.', 'Use it to separate ordinary grief guilt from thoughts worth examining more closely.', array['Adults', 'Teens']::text[], 'One session', 'List every ''if only I had...'' or ''I should have...'' thought the client is carrying about the loss, one per row, then sort each into a column for things that were genuinely within their control at the time, things that were not, and things that are unclear. Most rows land in the second or third column once written out plainly, which the writing itself tends to reveal better than talking about it in the abstract. For any thought that stays genuinely unresolved, flag it for its own conversation rather than forcing a verdict here.', '[{"id": "f0", "type": "textarea", "label": "If-only thoughts I''m carrying, one per line"}, {"id": "f1", "type": "textarea", "label": "Which were within my control at the time"}, {"id": "f2", "type": "textarea", "label": "Which were not"}, {"id": "f3", "type": "textarea", "label": "Which are still unclear to me"}]'::jsonb, array['grief and loss', 'self-blame', 'responsibility']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('grief-feelings-mix-up-drawing', 'Grief Feelings Mix-Up Drawing', 'kids'::resource_kind, 'A drawing activity where a child colors the tangled, sometimes contradictory feelings of a loss.', 'Use it to normalize a child having mixed or confusing feelings after someone dies.', array['Children']::text[], '30 minutes', 'Give the child a big scribbled or swirled outline and have them color different sections in different colors for each feeling they have about the loss, including ones that might feel confusing to admit, like relief or anger alongside sadness. The parent''s role is to name that all of the colors are allowed to be there at once, without asking the child to pick just one. If a child discloses something concerning about the circumstances of the loss while drawing, the clinician''s reporting duties apply as usual.', '[{"id": "f0", "type": "textarea", "label": "My mixed-up feelings drawing"}, {"id": "f1", "type": "textarea", "label": "Colors and what feeling each one is"}, {"id": "f2", "type": "textarea", "label": "The color that surprised me most"}, {"id": "f3", "type": "textarea", "label": "Who I can tell about this drawing"}]'::jsonb, array['grief and loss', 'children', 'art']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('grief-dice-reflection-game', 'Grief Dice Reflection Game', 'game'::resource_kind, 'A dice game where each number prompts a short reflection on the person or thing that was lost.', 'Use it to open grief conversation through low-pressure turn-taking rather than questions.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Assign each number one through six a short prompt — a memory that makes you smile, something you''d say if you had one more minute, something that''s changed since the loss, a color or smell that reminds you of them — and take turns rolling and answering, passing if a prompt doesn''t land that day. In a group, let each person roll once per round rather than racing through all six. Close with a debrief question: which prompt was the easiest to answer today, and would that have been true a year ago?', '[{"id": "f0", "type": "textarea", "label": "Prompts each number landed on for me"}, {"id": "f1", "type": "textarea", "label": "The prompt that was easiest to answer"}, {"id": "f2", "type": "textarea", "label": "The prompt I passed on, if any"}, {"id": "f3", "type": "textarea", "label": "What I noticed answering out loud versus thinking it privately"}]'::jsonb, array['grief and loss', 'bereavement']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('grieving-at-different-paces-conversation', 'Grieving at Different Paces Conversation', 'couples'::resource_kind, 'A structured talk for partners grieving the same loss in visibly different ways and speeds.', 'Use it to stop a mismatched grieving pace from being read as one partner not caring.', array['Couples']::text[], '30 minutes', 'Each partner describes how their own grief tends to show up and how long it typically takes them to feel steady again after a wave, then each names one thing the other partner does while grieving that they''ve privately misread — too quiet, too busy, too emotional. Partners commonly assume a different pace means a different depth of feeling; naming the misread directly, in session, usually does more to close that gap than either partner reassuring the other that they do, in fact, care.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how my grief tends to show up"}, {"id": "f1", "type": "textarea", "label": "Partner B: how my grief tends to show up"}, {"id": "f2", "type": "textarea", "label": "Partner A: one thing I''ve misread in Partner B"}, {"id": "f3", "type": "textarea", "label": "Partner B: one thing I''ve misread in Partner A"}, {"id": "f4", "type": "textarea", "label": "One thing we want to remember about each other''s pace"}]'::jsonb, array['grief and loss', 'conflict', 'relationship issues']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('outside-stress-spillover-chart', 'Outside Stress Spillover Chart', 'worksheet'::resource_kind, 'Maps how stress from work, money, or family leaks into how partners treat each other at home.', 'Use it to separate what a couple is fighting about from what is actually stressing them.', array['Adults', 'Couples']::text[], '20 minutes', 'Each partner lists the outside pressures currently weighing on them, then marks which ones tend to show up as short tempers, withdrawal, or snapping at home. Comparing the two lists in session often reveals that a couple has been treating spillover as a relationship problem when it is really an overload problem. Watch for partners who resist naming their own stress and instead point only to the other''s behavior; gently redirect them to their own list first.', '[{"id": "f0", "type": "textarea", "label": "Outside pressures I''m carrying right now"}, {"id": "f1", "type": "textarea", "label": "How that pressure tends to show up at home"}, {"id": "f2", "type": "textarea", "label": "What my partner might be carrying that I haven''t asked about"}, {"id": "f3", "type": "textarea", "label": "One thing that would help take the edge off this week"}]'::jsonb, array['relationship issues', 'stress', 'conflict']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('soft-emotion-finder-for-couples', 'Soft Emotion Finder for Couples', 'couples'::resource_kind, 'A guided exchange where each partner looks past the reactive emotion to the softer one underneath it.', 'Use it to help partners hear the vulnerable feeling driving a reaction instead of just the reaction.', array['Adults', 'Couples']::text[], '30 minutes', 'Partner A names the reactive emotion that shows up first in conflict, like anger or annoyed silence, then works backward with the clinician to find the softer emotion underneath it, like fear of not mattering or feeling shut out. Partner B does the same. Reading both softer-emotion statements aloud, without rebuttal, tends to shift the tone of the room faster than any amount of arguing about who''s right. Keep it in session the first few times; it can misfire if sent home too early.', '[{"id": "f0", "type": "textarea", "label": "Partner A: the reactive emotion I show first"}, {"id": "f1", "type": "textarea", "label": "Partner A: the softer feeling underneath it"}, {"id": "f2", "type": "textarea", "label": "Partner B: the reactive emotion I show first"}, {"id": "f3", "type": "textarea", "label": "Partner B: the softer feeling underneath it"}, {"id": "f4", "type": "textarea", "label": "What I want my partner to understand about that softer feeling"}]'::jsonb, array['relationship issues', 'EFT', 'emotion identification']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('stay-present-willingness-practice', 'Stay Present Willingness Practice', 'act'::resource_kind, 'A short practice for staying present through a hard conversation instead of shutting down or walking out.', 'Use it to build a partner''s willingness to stay engaged through relationship discomfort.', array['Adults', 'Couples']::text[], '15 minutes', 'Before a known hard conversation, the client rates how willing they are to stay engaged even if it gets uncomfortable, separate from how much they want to have the conversation at all. During it they notice the urge to withdraw, shut down, or escalate, and practice naming that urge silently and choosing to stay a little longer. Debrief afterward on what showed up in the body and what made staying possible. This is about willingness, not enduring harm; if a conversation turns unsafe, stepping away is still the right call.', '[{"id": "f0", "type": "textarea", "label": "The hard conversation I''m about to have"}, {"id": "f1", "type": "textarea", "label": "My willingness to stay engaged, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What urge to leave or shut down showed up"}, {"id": "f3", "type": "textarea", "label": "What helped me stay a little longer"}, {"id": "f4", "type": "textarea", "label": "What I noticed in my body during it"}]'::jsonb, array['relationship issues', 'willingness', 'defusion']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('partner-mind-reading-check', 'Partner Mind-Reading Check', 'cbt'::resource_kind, 'Catches the assumptions a client makes about a partner''s intentions before checking them out loud.', 'Use it to separate what a partner actually said from what the client assumed they meant.', array['Adults', 'Couples']::text[], '15 minutes', 'After a tense moment, the client writes down what they assumed their partner meant or intended, then rates how certain they were versus how much they actually asked. Most clients are surprised how rarely they check an assumption before reacting to it. In session, walk through one or two entries and role-play the checking-out question they skipped. This works best paired with an agreement that the partner will answer checking-out questions honestly rather than getting defensive.', '[{"id": "f0", "type": "textarea", "label": "What my partner said or did"}, {"id": "f1", "type": "textarea", "label": "What I assumed it meant"}, {"id": "f2", "type": "textarea", "label": "How certain I was, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "Did I check it out before reacting?"}, {"id": "f4", "type": "textarea", "label": "What I could ask next time instead of assuming"}]'::jsonb, array['relationship issues', 'thinking traps', 'automatic thoughts']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('middle-path-compromise-card', 'Middle Path Compromise Card', 'dbt'::resource_kind, 'Walks a couple through finding a middle path between two positions instead of an all-or-nothing outcome.', 'Use it to help partners find workable middle ground on a recurring disagreement.', array['Adults', 'Couples']::text[], '20 minutes', 'Each partner states their position on a recurring disagreement in one sentence, then both list what they''d lose if the other''s position simply won outright. The clinician helps them generate two or three middle-path options that honor a piece of each side rather than declaring one partner right. This isn''t the same as splitting the difference; some middle paths look more like taking turns or trying one approach for two weeks and reviewing it. Note which partner tends to over-concede and check in with them directly.', '[{"id": "f0", "type": "textarea", "label": "Partner A''s position"}, {"id": "f1", "type": "textarea", "label": "Partner B''s position"}, {"id": "f2", "type": "textarea", "label": "What Partner A would lose if B''s position simply won"}, {"id": "f3", "type": "textarea", "label": "What Partner B would lose if A''s position simply won"}, {"id": "f4", "type": "textarea", "label": "A middle-path option we''re willing to try"}]'::jsonb, array['relationship issues', 'middle path', 'dialectics']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('safety-cues-checklist', 'Safety Cues Checklist', 'worksheet'::resource_kind, 'A checklist of present-moment sights, sounds, and sensations that remind the body it is safe right now.', 'Use it to build a fast, reliable way to locate safety cues when the body feels on alert.', array['Adults', 'Teens']::text[], '10 minutes', 'In session, the client scans the current room and their own body for concrete signs that this moment is safe: a locked door, a steady chair, a calm voice, feet on the floor. They write each one down in plain, checkable language rather than a feeling, so it can be scanned for quickly under stress. Practice the scan a few times in session before it becomes a grounding reference, never an assignment to process anything. This stays entirely in the present; it is not a place to write out what happened.', '[{"id": "f0", "type": "textarea", "label": "Something I can see right now that tells me I''m safe"}, {"id": "f1", "type": "textarea", "label": "Something I can hear right now"}, {"id": "f2", "type": "textarea", "label": "Something I can feel or touch right now"}, {"id": "f3", "type": "textarea", "label": "One safety cue I want to remember for later"}]'::jsonb, array['sexual abuse', 'grounding', 'safety planning']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('body-alarm-volume-dial', 'Body Alarm Volume Dial', 'cbt'::resource_kind, 'Tracks how loud the body''s alarm feels in the moment and what turns the volume down.', 'Use it to give a client language for rising body alarm before it peaks.', array['Adults', 'Teens']::text[], 'Five minutes daily for several weeks', 'The client rates their body''s alarm level on a 0-to-10 dial several times a day, noting only the number, the situation, and one thing that helped bring it down, never the content of any memory. Over a week or two this usually surfaces a pattern of times and places where the dial runs high, which becomes something to plan around rather than something to explain. Keep the focus on the dial and the turn-down strategy in session; redirect gently if the client starts narrating details instead.', '[{"id": "f0", "type": "textarea", "label": "Time and situation"}, {"id": "f1", "type": "textarea", "label": "Alarm level, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "What helped turn the dial down"}, {"id": "f3", "type": "textarea", "label": "Alarm level after"}]'::jsonb, array['sexual abuse', 'PTSD and trauma', 'regulation']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('flashback-distraction-menu', 'Flashback Distraction Menu', 'dbt'::resource_kind, 'A ranked menu of grounding and distraction skills a client can reach for the moment a flashback starts.', 'Use it to shorten how long a flashback runs before the client can re-orient to the present.', array['Adults', 'Teens']::text[], '15 minutes to build, then ongoing', 'Build the menu together in session: five or six concrete, fast actions the client can take the instant they notice a flashback starting, ranked from what works fastest to what works best when there''s more time. Test one or two in session so the client has already felt them work once before needing them alone. This is a menu of actions to take, not a place to record what the flashback was about; keep any processing of content for separate session time, not the card itself.', '[{"id": "f0", "type": "textarea", "label": "My fastest go-to action when a flashback starts"}, {"id": "f1", "type": "textarea", "label": "A second option if the first doesn''t work"}, {"id": "f2", "type": "textarea", "label": "Something that helps me remember what year it is"}, {"id": "f3", "type": "textarea", "label": "Who I can text or call afterward"}]'::jsonb, array['sexual abuse', 'distress tolerance', 'grounding']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('my-safe-grown-ups-map', 'My Safe Grown-Ups Map', 'kids'::resource_kind, 'A drawing activity where a child maps the trusted adults they can go to if something feels wrong.', 'Use it to give a child a clear, rehearsed list of safe adults before they need one.', array['Children']::text[], '20 minutes', 'The child draws or writes the names of adults at home, school, and in their extended family who they''d feel okay telling if something felt confusing, scary, or wrong, and the clinician talks through what telling a safe grown-up might sound like. Keep the activity about identifying people and practicing the words, not about any specific event. If a child discloses anything during this or any session, the clinician''s mandatory reporting duties apply regardless of what stage of the work this is; pause the activity and follow your reporting process.', '[{"id": "f0", "type": "textarea", "label": "Draw or write the safe grown-ups in your life"}, {"id": "f1", "type": "textarea", "label": "What could you say to a safe grown-up if something felt wrong?"}, {"id": "f2", "type": "textarea", "label": "What would you want the grown-up to do next?"}]'::jsonb, array['sexual abuse', 'body safety', 'disclosure']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('pacing-and-support-card-for-partners', 'Pacing and Support Card for Partners', 'couples'::resource_kind, 'Helps a partner learn how to offer steady support without pressuring pace, closeness, or disclosure.', 'Use it to give a supporting partner concrete, non-pressuring ways to show up.', array['Adults', 'Couples']::text[], '20 minutes', 'The supporting partner and the client separately note what kinds of check-ins, touch, or closeness currently feel supportive versus pressuring, then compare notes in session with the clinician present. The goal is a short shared list of low-pressure ways the partner can show care, plus a simple signal the client can use to ask for more space without a long explanation. This stays focused on present-day pacing and support; it is not the place to revisit what happened or work through it as a couple''s assignment.', '[{"id": "f0", "type": "textarea", "label": "Client: what feels supportive right now"}, {"id": "f1", "type": "textarea", "label": "Client: what feels like pressure right now"}, {"id": "f2", "type": "textarea", "label": "Partner: how I can check in without pushing"}, {"id": "f3", "type": "textarea", "label": "Our signal for ''I need space'' that doesn''t require explaining"}]'::jsonb, array['sexual abuse', 'support', 'pacing']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('coping-skill-effort-relief-grid', 'Coping Skill Effort-Relief Grid', 'worksheet'::resource_kind, 'Plots each coping skill on how much effort it takes against how much relief it actually brings.', 'Use it to help a client pick a coping skill that fits their current capacity, not just their goal.', array['Adults', 'Teens']::text[], '15 minutes', 'List the coping skills the client already uses, then place each one on a simple grid: low to high effort on one axis, low to high relief on the other. Skills that take a lot of energy but bring little relief are often the ones a client keeps reaching for out of habit; skills in the low-effort, high-relief corner are worth having ready for low-capacity days. Revisit the grid every few weeks, since effort and relief can shift with practice or with how depleted the client currently is.', '[{"id": "f0", "type": "textarea", "label": "Coping skill"}, {"id": "f1", "type": "textarea", "label": "Effort it takes, low to high"}, {"id": "f2", "type": "textarea", "label": "Relief it brings, low to high"}, {"id": "f3", "type": "textarea", "label": "When I''d reach for this one"}]'::jsonb, array['coping skills', 'self-monitoring', 'skills']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('building-mastery-activity-planner', 'Building Mastery Activity Planner', 'dbt'::resource_kind, 'Schedules one small, doable activity a day chosen to build a sense of competence, not just to feel calm.', 'Use it to build a client''s confidence that they can handle things, one small task at a time.', array['Adults', 'Teens']::text[], 'One week', 'Each day the client picks one activity slightly harder than what feels easy but well short of overwhelming, something that leaves them thinking ''I did that.'' It can be as small as cooking one meal from scratch or finishing a load of laundry start to finish. Unlike most coping skills, the point isn''t to calm down in the moment; it''s to slowly build evidence that the client is capable, which tends to lower the baseline urge to reach for other coping skills at all. Log what was planned and what actually happened, gaps included.', '[{"id": "f0", "type": "textarea", "label": "Activity I''m planning today"}, {"id": "f1", "type": "textarea", "label": "Did I follow through?"}, {"id": "f2", "type": "textarea", "label": "How capable I felt afterward, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What got in the way, if anything"}]'::jsonb, array['coping skills', 'core DBT', 'self-monitoring']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('acceptance-or-avoidance-coping-sort', 'Acceptance or Avoidance Coping Sort', 'act'::resource_kind, 'Sorts a client''s usual coping strategies by whether they make room for a hard feeling or push it away.', 'Use it to help a client see which coping skills work with difficult feelings and which just avoid them.', array['Adults', 'Teens']::text[], '15 minutes', 'List the coping skills the client currently reaches for, then sort each one into ''makes room for the feeling'' or ''pushes the feeling away,'' noting that both categories can include skills the client isn''t ready to give up. Avoidance-leaning skills aren''t labeled wrong; the point is simply naming which is which, since a coping skill that always pushes a feeling away can quietly keep that feeling in charge. Use the sort to pick one acceptance-leaning skill to practice alongside the client''s existing go-tos, not to replace them all at once.', '[{"id": "f0", "type": "textarea", "label": "Coping skill I use"}, {"id": "f1", "type": "textarea", "label": "Does it make room for the feeling or push it away?"}, {"id": "f2", "type": "textarea", "label": "What happens to the feeling afterward?"}, {"id": "f3", "type": "textarea", "label": "One acceptance-leaning skill I could try alongside it"}]'::jsonb, array['coping skills', 'acceptance', 'avoidance']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('coping-skills-treasure-box', 'Coping Skills Treasure Box', 'kids'::resource_kind, 'A decorated box a child fills with drawn or written reminders of coping skills that work for them.', 'Use it to give a child a physical, personalized place to find coping ideas in the moment.', array['Children']::text[], '30 minutes to build, then ongoing', 'The child decorates a small box in session, then fills it over time with index cards, drawings, or small objects that represent coping skills that have worked for them, like a card with a drawn breathing shape or a smooth stone that reminds them of a calm-down spot. The caregiver keeps the box somewhere the child can reach it independently and prompts ''want to check your box?'' during a rough moment instead of listing skills themselves. Refresh the box together every few weeks so it keeps matching what actually helps.', '[{"id": "f0", "type": "textarea", "label": "Draw or write a coping skill for your box"}, {"id": "f1", "type": "textarea", "label": "When would you use this one?"}, {"id": "f2", "type": "textarea", "label": "Caregiver: where will the box live at home?"}]'::jsonb, array['coping skills', 'art', 'children']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('coping-skills-bingo', 'Coping Skills Bingo', 'game'::resource_kind, 'A bingo board of small coping actions that players complete for real during the game, not just imagine.', 'Use it to get a group physically practicing coping skills instead of only naming them.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Each square names a quick coping action, like taking five slow breaths, naming three things you can see, or doing ten jumping jacks. Players take turns rolling or drawing a square and actually doing the action on the spot before marking it, so the board gets practiced rather than just read. First to five in a row calls bingo, then the group debriefs with one question: which square would you actually reach for on a hard day? Keep the tone light and let a shy player pass a square rather than freeze the game on them.', '[{"id": "f0", "type": "textarea", "label": "Which square did you like doing most?"}, {"id": "f1", "type": "textarea", "label": "Which square would you actually use on a hard day?"}, {"id": "f2", "type": "textarea", "label": "One coping action you''d add to the board"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('avoidance-ripple-map', 'Avoidance Ripple Map', 'worksheet'::resource_kind, 'Traces how avoiding a feared object or situation quietly limits other areas of a client''s life.', 'Use it to show a client the real cost of avoidance beyond the moment of fear itself.', array['Adults', 'Teens']::text[], '20 minutes', 'Starting from the feared object or situation in the center, the client maps outward to everything they''ve rearranged around it: routes not taken, invitations declined, plans quietly dropped. Most clients have never laid the ripple out in one place before and are surprised by its reach. Use the map to build the case for working on the phobia collaboratively, not to argue the client into exposure before they''re ready; the ripple itself is the motivator, not the clinician''s pressure.', '[{"id": "f0", "type": "textarea", "label": "The feared object or situation"}, {"id": "f1", "type": "textarea", "label": "Places or routes I avoid because of it"}, {"id": "f2", "type": "textarea", "label": "Plans or invitations I''ve turned down because of it"}, {"id": "f3", "type": "textarea", "label": "People or relationships it has quietly affected"}]'::jsonb, array['phobias', 'avoidance', 'exposure']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('feared-object-fact-file', 'Feared Object Fact File', 'cbt'::resource_kind, 'A factual reference sheet the client and clinician build together about the specific feared object or situation.', 'Use it to give a client accurate information to weigh against their fear-driven predictions.', array['Adults', 'Teens']::text[], '20 minutes', 'Together, the client and clinician gather plain factual information about the feared object or situation, the kind that''s checkable rather than reassuring, and write it in the client''s own words alongside the scarier belief it counters. The point isn''t to talk the client out of fear in one sitting; it''s to have a written, factual anchor they can return to when the fear voice gets loud. Keep entries specific and sourced from the client''s own research or the clinician''s knowledge, not vague reassurance.', '[{"id": "f0", "type": "textarea", "label": "The feared object or situation"}, {"id": "f1", "type": "textarea", "label": "What my fear tells me about it"}, {"id": "f2", "type": "textarea", "label": "A fact I can check that speaks to this"}, {"id": "f3", "type": "textarea", "label": "What I actually found out"}]'::jsonb, array['phobias', 'cognitive flexibility', 'psychoeducation']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('fear-voice-vs-fact-sort-for-kids', 'Fear Voice vs Fact Sort for Kids', 'kids'::resource_kind, 'A card sort where a child separates scary thoughts about a feared thing from what''s actually true about it.', 'Use it to help a child notice the difference between a scary thought and a fact.', array['Children']::text[], '20 minutes', 'Write several statements about the feared object on cards, some scary thoughts and some plain facts, and have the child sort them into two piles: ''fear voice'' and ''fact.'' Talk through each card together, especially ones the child sorts differently than expected. Caregivers can keep a small set of fact cards at home to read together before an approach step, giving the child a script to reach for instead of only reassurance from an adult in the moment.', '[{"id": "f0", "type": "textarea", "label": "Sort this card: fear voice or fact?"}, {"id": "f1", "type": "textarea", "label": "A fear voice thought I have about it"}, {"id": "f2", "type": "textarea", "label": "A fact I now know about it"}]'::jsonb, array['phobias', 'children', 'cognitive flexibility']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('brave-steps-board-game', 'Brave Steps Board Game', 'game'::resource_kind, 'A family board game where landing on a square means taking one small real step toward a feared object.', 'Use it to make approach steps feel like play instead of a test to pass or fail.', array['Children', 'Teens']::text[], '20 minutes', 'Build a simple path board together with the child, where most squares are silly family-game moves and every fourth or fifth square is a real, pre-agreed approach step toward the feared object, ranked easiest to hardest along the path. Roll a die and move; landing on a step square means doing that step, in session or at home with a caregiver, before the next turn. End every round with one debrief question: what was easier or harder than you expected? Keep steps small enough that most turns feel winnable.', '[{"id": "f0", "type": "textarea", "label": "Approach step for this square"}, {"id": "f1", "type": "textarea", "label": "What was easier or harder than I expected?"}, {"id": "f2", "type": "textarea", "label": "What I''d want to try next"}]'::jsonb, array['phobias', 'exposure', 'children']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('willingness-dial-for-approach-steps', 'Willingness Dial for Approach Steps', 'act'::resource_kind, 'Swaps a fear rating for a willingness rating so approach steps track courage rather than comfort.', 'Use it to help a client take approach steps even while fear stays high, not only once it drops.', array['Adults', 'Teens']::text[], '15 minutes', 'Before each approach step, the client rates their willingness to take the step, separate from and often quite different from their fear level, which usually stays high the whole time. The goal on any given step is a willingness of ''enough,'' not a fear of zero, which frees the client from waiting to feel ready before they act. Log both numbers side by side across steps; clients are often surprised to see willingness climb over weeks even while fear barely moves.', '[{"id": "f0", "type": "textarea", "label": "Approach step"}, {"id": "f1", "type": "textarea", "label": "Fear level, 0 to 10"}, {"id": "f2", "type": "textarea", "label": "Willingness to do it anyway, 0 to 10"}, {"id": "f3", "type": "textarea", "label": "What I noticed after taking the step"}]'::jsonb, array['phobias', 'willingness', 'exposure']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('appearance-avoidance-log', 'Appearance Avoidance Log', 'worksheet'::resource_kind, 'Tracks situations a client skips or shrinks from because of how they feel about their appearance.', 'Use it to map how much of daily life appearance worry is currently steering.', array['Adults', 'Teens']::text[], 'One week', 'Each time the client avoids, cuts short, or over-prepares for a situation because of how they feel about their appearance, they note the situation and what they did instead of just showing up as they were. Common entries include skipping a pool invite, over-checking an outfit for an hour, or avoiding a photo. Reviewing the week together usually reveals a pattern of situations worth targeting first, chosen for what matters most to the client rather than what feels scariest.', '[{"id": "f0", "type": "textarea", "label": "Situation I avoided or changed"}, {"id": "f1", "type": "textarea", "label": "What I did instead of just showing up"}, {"id": "f2", "type": "textarea", "label": "What I was worried would happen"}, {"id": "f3", "type": "textarea", "label": "One situation I''d like to try differently next week"}]'::jsonb, array['body image', 'avoidance', 'self-monitoring']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('mirror-check-behavioral-experiment', 'Mirror Check Behavioral Experiment', 'cbt'::resource_kind, 'A behavioral experiment testing what actually happens when a client changes how long or how often they check the mirror.', 'Use it to test a client''s predictions about mirror checking against what actually happens.', array['Adults', 'Teens']::text[], 'One week', 'Together, set a specific prediction about what will happen if the client shortens a mirror check or skips a between-check ritual, then have them run the experiment and record what actually happened against the prediction. Some clients predict a spike in anxiety that never comes; others notice the anxiety comes and passes faster than expected once the checking loop is interrupted. Keep the experiment small and specific rather than an open-ended ban on mirrors, and review results together before scaling it up.', '[{"id": "f0", "type": "textarea", "label": "My prediction if I shorten or skip this check"}, {"id": "f1", "type": "textarea", "label": "What I actually did"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "How my prediction compared to reality"}]'::jsonb, array['body image', 'behavioral experiment', 'self-monitoring']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('dress-for-values-practice', 'Dress for Values Practice', 'act'::resource_kind, 'Has a client choose what to wear based on comfort and values instead of appearance-anxiety rules.', 'Use it to build committed action around dressing in line with what matters, not what fear dictates.', array['Adults', 'Teens']::text[], 'One week', 'The client names what actually matters to them about a day ahead, like connection, comfort, or showing up fully, then chooses an outfit based on that value rather than on appearance-anxiety rules they''d normally follow, such as extra layers or a specific covering item. Afterward they note what thought or urge showed up and whether they acted on the value anyway. This works best started with lower-stakes days before trying it ahead of something the client has been avoiding.', '[{"id": "f0", "type": "textarea", "label": "What matters to me about today"}, {"id": "f1", "type": "textarea", "label": "What I chose to wear based on that"}, {"id": "f2", "type": "textarea", "label": "What appearance-anxiety thought showed up"}, {"id": "f3", "type": "textarea", "label": "Did I act on my value anyway?"}]'::jsonb, array['body image', 'values', 'committed action']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('all-kinds-of-bodies-sort', 'All Kinds of Bodies Sort', 'kids'::resource_kind, 'A card sort where a child matches all kinds of bodies to all the things bodies let people do.', 'Use it to build a child''s sense that bodies come in many forms and all of them do things.', array['Children']::text[], '20 minutes', 'Lay out cards showing bodies of many different shapes, sizes, and abilities alongside cards showing activities like climbing, hugging, dancing, or resting, and have the child match activity cards to body cards, noticing that every body card can pair with several activities. Talk through any comment the child makes about a body being ''better'' or ''worse,'' gently widening it back to what that body can do. Caregivers can keep the language function-first at home, praising what a body does rather than how it looks.', '[{"id": "f0", "type": "textarea", "label": "Which activities did you match to this body?"}, {"id": "f1", "type": "textarea", "label": "What''s something your own body lets you do?"}, {"id": "f2", "type": "textarea", "label": "Caregiver: a function-focused comment to try at home"}]'::jsonb, array['body image', 'children', 'self-esteem']::text[], '2026-09-17T15:00:00+00:00'::timestamptz),
  ('function-toss-game', 'Function Toss Game', 'game'::resource_kind, 'A toss-and-share game where each catch prompts a player to name something their body let them do that day.', 'Use it to build a group habit of noticing what bodies do instead of how they look.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Players stand in a circle and toss a soft ball; whoever catches it names one thing their body let them do that day, big or small, like climbing stairs, laughing, or carrying a backpack, then tosses it on. Keep the pace quick and playful, and if a player freezes, let them toss it along and try again next round rather than putting them on the spot. Close with one debrief question: did anything surprise you about what you heard from others?', '[{"id": "f0", "type": "textarea", "label": "Something your body let you do today"}, {"id": "f1", "type": "textarea", "label": "Something you heard from someone else that surprised you"}, {"id": "f2", "type": "textarea", "label": "One thing your body does every day that you don''t usually think about"}]'::jsonb, array['body image', 'gratitude', 'group']::text[], '2026-09-17T15:00:00+00:00'::timestamptz)
